export const MATH_HTML: string = "<!doctype html>\n<html lang=\"fr\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<title>Atelier Maths SN4 | e-formation.net</title>\n<meta name=\"robots\" content=\"noindex\">\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:opsz,wght@12..96,600;12..96,800&family=Instrument+Sans:wght@400;500;600&family=STIX+Two+Text:ital,wght@0,400;0,600;1,400&display=swap\">\n<style>\n/* Concept : cahier quadrill\u00e9. Papier \u00e0 carreaux, encre indigo, surligneur jaune pour l'essentiel. */\n:root{\n  --bg:#f2f3fa; --paper:#fcfcff; --grid:rgba(75,50,195,.08);\n  --ink:#1c1a35; --muted:#5b5877; --line:#d9d7ea;\n  --accent:#4b32c3; --accent-ink:#ffffff; --accent-soft:#ebe8fb;\n  --hi:#ffe27a; --ok:#0b7a55; --ok-soft:#dcf5ea; --bad:#b42318; --bad-soft:#fde8e6;\n  --f-display:'Bricolage Grotesque',system-ui,sans-serif;\n  --f-body:'Instrument Sans',system-ui,-apple-system,sans-serif;\n  --f-math:'STIX Two Text','Cambria Math',Georgia,serif;\n}\n@media (prefers-color-scheme: dark){:root:not([data-theme=\"light\"]){\n  --bg:#13122a; --paper:#1b1a38; --grid:rgba(150,135,255,.08);\n  --ink:#ecebfa; --muted:#a8a5c9; --line:#33315e;\n  --accent:#a496ff; --accent-ink:#17142e; --accent-soft:#2a2756;\n  --hi:#5b4b00; --ok:#56d6a6; --ok-soft:#133a30; --bad:#ff9087; --bad-soft:#41201f; color-scheme:dark}}\n:root[data-theme=\"dark\"]{\n  --bg:#13122a; --paper:#1b1a38; --grid:rgba(150,135,255,.08);\n  --ink:#ecebfa; --muted:#a8a5c9; --line:#33315e;\n  --accent:#a496ff; --accent-ink:#17142e; --accent-soft:#2a2756;\n  --hi:#5b4b00; --ok:#56d6a6; --ok-soft:#133a30; --bad:#ff9087; --bad-soft:#41201f; color-scheme:dark}\n\n*{box-sizing:border-box}\nbody{margin:0;background-color:var(--bg);color:var(--ink);font:16px/1.6 var(--f-body);\n  background-image:linear-gradient(var(--grid) 1px,transparent 1px),linear-gradient(90deg,var(--grid) 1px,transparent 1px);\n  background-size:24px 24px;\n  padding-left:max(16px,env(safe-area-inset-left,0px));padding-right:max(16px,env(safe-area-inset-right,0px));padding-block:0 48px}\nbody::before{content:\"\";position:fixed;inset:0 0 auto;height:env(safe-area-inset-top,0px);z-index:30;background:var(--paper)}\n.wrap{max-width:960px;margin:0 auto}\na{color:var(--accent)}\nh1,h2,h3{font-family:var(--f-display);line-height:1.15;margin:0;text-wrap:balance}\nh1{font-size:clamp(2rem,6vw,3.2rem);font-weight:800;letter-spacing:-.02em}\nh2{font-size:1.35rem;font-weight:800}\nh3{font-size:1.08rem;font-weight:600}\np{margin:0 0 .8em}\n.eyebrow{font-size:.78rem;letter-spacing:.12em;text-transform:uppercase;color:var(--muted);font-weight:600;margin:0 0 .6rem}\n.muted{color:var(--muted)}\nsup,sub{font-size:.7em;line-height:0}\n.fr{display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;line-height:1.15;margin:0 .15em;font-family:var(--f-math)}\n.fr>span:first-child{border-bottom:1.5px solid currentColor;padding:0 .25em}\n.fr>span:last-child{padding:0 .25em}\n.rad{font-family:var(--f-math)}\n.rc{border-top:1.5px solid currentColor;padding:0 .12em;margin-left:1px}\n.m{font-family:var(--f-math);font-size:1.08em}\n\n/* header */\n.top{position:sticky;top:env(safe-area-inset-top,0px);z-index:20;background:var(--paper);border-bottom:1px solid var(--line);\n  margin-inline:calc(-1*max(16px,env(safe-area-inset-left,0px))) calc(-1*max(16px,env(safe-area-inset-right,0px)));\n  padding-inline:max(16px,env(safe-area-inset-left,0px)) max(16px,env(safe-area-inset-right,0px))}\n.top .wrap{display:flex;align-items:center;gap:1rem;flex-wrap:wrap;padding-block:.6rem}\n.brand{font-family:var(--f-display);font-weight:800;text-decoration:none;color:var(--ink);font-size:1.1rem;margin-right:auto}\n.brand b{background:var(--hi);padding:0 .3em;border-radius:3px}\nnav{display:flex;gap:.25rem;flex-wrap:wrap}\nnav a{padding:.4rem .8rem;border-radius:999px;text-decoration:none;color:var(--muted);font-weight:600;font-size:.92rem}\nnav a:hover{color:var(--ink)}\nnav a[aria-current=\"page\"]{background:var(--accent);color:var(--accent-ink)}\na:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid var(--accent);outline-offset:2px}\n\nmain{padding-top:2rem}\n.intro{display:grid;gap:.9rem;margin-bottom:2rem}\n.intro p.lead{font-size:1.12rem;max-width:60ch;color:var(--muted)}\n.intro h1 mark{background:var(--hi);color:inherit;padding:0 .12em;border-radius:4px}\n.summary{display:flex;gap:1.5rem;flex-wrap:wrap;font-weight:600}\n.summary span b{font-family:var(--f-display);font-size:1.5rem;margin-right:.3rem}\n\n.list{display:grid;gap:.75rem;margin:0 0 2.2rem;padding:0;list-style:none}\n.row{display:grid;grid-template-columns:auto minmax(0,1fr) auto;gap:1rem;align-items:center;background:var(--paper);border:1px solid var(--line);border-radius:12px;padding:1rem 1.1rem}\n.num{font-family:var(--f-display);font-weight:800;font-size:1.7rem;color:var(--accent);min-width:2ch;text-align:center}\n.row p{margin:.15rem 0 .5rem;color:var(--muted);font-size:.92rem}\n.bar{height:6px;background:var(--accent-soft);border-radius:99px;overflow:hidden;max-width:320px}\n.bar i{display:block;height:100%;background:var(--accent);border-radius:99px}\n.best{font-size:.8rem;color:var(--muted);margin-top:.3rem}\n.acts{display:flex;gap:.5rem;flex-wrap:wrap}\n.btn,.btn-s{font:600 .95rem var(--f-body);padding:.6rem 1.1rem;border-radius:10px;text-decoration:none;cursor:pointer;border:1.5px solid var(--accent);display:inline-block}\n.btn{background:var(--accent);color:var(--accent-ink)}\n.btn:hover{filter:brightness(1.08)}\n.btn-s{background:transparent;color:var(--accent)}\n.btn-s:hover{background:var(--accent-soft)}\nbutton:disabled{opacity:.45;cursor:not-allowed}\n@media (max-width:620px){.row{grid-template-columns:auto minmax(0,1fr)}.acts{grid-column:1/-1}}\n\n.two{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:1rem;margin-bottom:2.2rem}\n.panel{background:var(--paper);border:1px solid var(--line);border-radius:12px;padding:1.2rem 1.3rem;min-width:0}\n.panel h2{margin-bottom:.4rem}\n.hist{list-style:none;margin:0;padding:0;display:grid;gap:.4rem;font-size:.93rem}\n.hist li{display:flex;justify-content:space-between;gap:1rem;border-bottom:1px dashed var(--line);padding-bottom:.35rem}\n\n/* chapter */\n.crumb{display:flex;justify-content:space-between;gap:1rem;flex-wrap:wrap;font-size:.9rem;margin-bottom:1rem}\n.tabs{display:flex;gap:.4rem;margin:1rem 0 1.5rem}\n.tabs a{padding:.5rem 1rem;border-radius:10px;text-decoration:none;font-weight:600;border:1.5px solid var(--line);color:var(--muted);background:var(--paper)}\n.tabs a[aria-current=\"page\"]{border-color:var(--accent);color:var(--accent);background:var(--accent-soft)}\n.sec{background:var(--paper);border:1px solid var(--line);border-radius:12px;padding:1.2rem 1.4rem;margin-bottom:1rem}\n.sec h2{margin-bottom:.7rem}\n.sec ul{margin:0 0 .8em;padding-left:1.2em}\n.sec li{margin:.25em 0}\n.formula{font-family:var(--f-math);font-size:1.12rem;background:var(--accent-soft);border-left:4px solid var(--accent);padding:.7rem 1rem;border-radius:0 8px 8px 0;margin:.7rem 0;display:grid;gap:.3rem}\n.ex{border:1.5px dashed var(--line);border-radius:10px;padding:.7rem 1rem;margin:.8rem 0}\n.ex>b:first-child{background:var(--hi);padding:0 .35em;border-radius:3px;margin-right:.4rem;color:inherit}\n.tip{font-size:.95rem;color:var(--muted)}\n.cta{margin:1.5rem 0;display:flex;gap:.6rem;flex-wrap:wrap}\n\n/* explorer */\n.xp{display:grid;grid-template-columns:minmax(0,300px) minmax(0,1fr);gap:1.2rem;align-items:start}\n@media (max-width:640px){.xp{grid-template-columns:1fr}}\n.xp label{display:grid;grid-template-columns:2.2ch 1fr 5ch;gap:.6rem;align-items:center;margin:.4rem 0;font-family:var(--f-math);font-size:1.05rem}\n.xp input[type=range]{width:100%;accent-color:var(--accent)}\n.xp svg{width:100%;max-width:384px;height:auto;display:block;border:1px solid var(--line);border-radius:8px;background:var(--paper)}\n.readout{font-family:var(--f-math);display:grid;gap:.2rem;margin-top:.6rem;font-size:1.02rem}\n.gridl{stroke:var(--line);stroke-width:1}\n.axis{stroke:var(--muted);stroke-width:1.5}\n.curve{fill:none;stroke:var(--accent);stroke-width:2.5}\n.pt{fill:var(--bad)}\n.pz{fill:var(--ok)}\n.svgt{fill:var(--muted);font:10px var(--f-body)}\n\n/* quiz */\n.qhead{display:flex;justify-content:space-between;align-items:center;gap:1rem;flex-wrap:wrap;margin-bottom:.6rem}\n.timer{font-family:var(--f-display);font-weight:800;font-size:1.3rem;font-variant-numeric:tabular-nums;padding:.2rem .7rem;border-radius:8px;background:var(--accent-soft)}\n.timer.low{background:var(--bad-soft);color:var(--bad)}\n.qbar{height:8px;background:var(--accent-soft);border-radius:99px;overflow:hidden;margin-bottom:1.2rem}\n.qbar i{display:block;height:100%;background:var(--accent);transition:width .25s}\n.qlayout{display:grid;grid-template-columns:minmax(0,1fr) 190px;gap:1.2rem;align-items:start}\n@media (max-width:760px){.qlayout{grid-template-columns:1fr}}\n.qlayout.solo{grid-template-columns:minmax(0,1fr)}\n.qcard{background:var(--paper);border:1px solid var(--line);border-radius:12px;padding:1.3rem}\n.qtag{font-size:.8rem;color:var(--muted);margin-bottom:.5rem}\n.qtext{font-size:1.18rem;font-weight:500;margin-bottom:1rem}\n.opts{display:grid;gap:.55rem}\n.opt{display:grid;grid-template-columns:2rem minmax(0,1fr);gap:.7rem;align-items:center;text-align:left;font:500 1.05rem var(--f-math);color:var(--ink);background:var(--paper);border:1.5px solid var(--line);border-radius:10px;padding:.65rem .8rem;cursor:pointer;width:100%}\n.opt .l{font:700 .9rem var(--f-body);width:1.8rem;height:1.8rem;border-radius:50%;display:grid;place-items:center;background:var(--accent-soft);color:var(--accent)}\n.opt:hover:not(:disabled){border-color:var(--accent)}\n.opt.sel{border-color:var(--accent);background:var(--accent-soft)}\n.opt.good{border-color:var(--ok);background:var(--ok-soft)}\n.opt.bad{border-color:var(--bad);background:var(--bad-soft)}\n.opt:disabled{cursor:default;opacity:1}\n.expl{margin-top:1rem;padding:.8rem 1rem;border-radius:10px;background:var(--accent-soft);font-size:.98rem}\n.expl b.g{color:var(--ok)}.expl b.r{color:var(--bad)}\n.qnav{display:flex;justify-content:space-between;gap:.6rem;margin-top:1rem;flex-wrap:wrap}\n.navg{display:grid;grid-template-columns:repeat(auto-fill,minmax(36px,1fr));gap:.35rem}\n.navg button{font:600 .85rem var(--f-body);padding:.4rem 0;border-radius:8px;border:1.5px solid var(--line);background:var(--paper);color:var(--muted);cursor:pointer}\n.navg button.done{background:var(--accent-soft);color:var(--accent);border-color:var(--accent-soft)}\n.navg button.cur{border-color:var(--accent);color:var(--ink)}\n.warn{background:var(--bad-soft);color:var(--ink);border-radius:10px;padding:.8rem 1rem;margin-top:1rem}\n\n/* results */\n.score{display:flex;align-items:baseline;gap:1rem;flex-wrap:wrap;margin:.4rem 0 1rem}\n.score .big{font-family:var(--f-display);font-weight:800;font-size:clamp(2.6rem,9vw,4rem);line-height:1}\n.mention{font-weight:700;background:var(--hi);padding:.1rem .6rem;border-radius:6px;color:inherit}\n.bars{display:grid;gap:.5rem;margin:1rem 0}\n.bars div{display:grid;grid-template-columns:minmax(0,13rem) 1fr 4ch;gap:.7rem;align-items:center;font-size:.92rem}\n.bars .bar{max-width:none}\n.bars .bar i.lo{background:var(--bad)}\n.rev{display:grid;gap:.8rem;margin-top:1rem}\n.rev .qcard{padding:1rem 1.1rem}\n.rev .res-ok{color:var(--ok);font-weight:700}.rev .res-no{color:var(--bad);font-weight:700}\n.filters{display:flex;gap:.5rem;flex-wrap:wrap;margin-top:1.2rem}\n\n/* builder */\n.form{display:grid;gap:1rem}\n.chk{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:.4rem}\n.chk label,.inl label{display:flex;gap:.55rem;align-items:center;cursor:pointer}\n.inl{display:flex;gap:1.2rem;flex-wrap:wrap;align-items:center}\nselect,input[type=number]{font:500 1rem var(--f-body);padding:.4rem .6rem;border-radius:8px;border:1.5px solid var(--line);background:var(--paper);color:var(--ink)}\ninput[type=checkbox],input[type=radio]{accent-color:var(--accent);width:1.1rem;height:1.1rem}\n.presets{display:grid;gap:.75rem}\n.preset{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:1rem;align-items:center}\n@media (prefers-reduced-motion: reduce){*{transition:none!important}}\n:root{color-scheme:light}\n[hidden]{display:none!important}\n</style>\n</head>\n<body>\n\n<div class=\"top\"><div class=\"wrap\">\n  <a class=\"brand\" href=\"#accueil\"><b>Maths</b> SN4</a>\n  <nav id=\"nav\" aria-label=\"Navigation principale\">\n    <a href=\"#accueil\" data-k=\"accueil\">Accueil</a>\n    <a href=\"#tests\" data-k=\"tests\">Tests</a>\n    <a href=\"#examens\" data-k=\"examens\">Examens</a>\n  </nav>\n</div></div>\n<main class=\"wrap\" id=\"app\"></main>\n\n<script>\nwindow.CH = window.CH || [];\nCH.push({\nid:1, titre:\"La manipulation d'expressions alg\u00e9briques\",\nresume:\"Multiplication et division de polyn\u00f4mes, fractions alg\u00e9briques (expressions rationnelles).\",\ncours:[\n{h:\"La multiplication de polyn\u00f4mes\", html:`\n<p>On distribue chaque terme du premier facteur \u00e0 chaque terme du second, puis on regroupe les termes semblables. Le degr\u00e9 du produit est la somme des degr\u00e9s des facteurs.</p>\n<div class=\"formula\">\n<div>(a + b)(c + d) = ac + ad + bc + bd</div>\n<div>(a + b)^{2} = a^{2} + 2ab + b^{2} &nbsp;&nbsp; (a + b)(a \u2212 b) = a^{2} \u2212 b^{2}</div>\n</div>\n<div class=\"ex\"><b>Exemple</b> (2x \u2212 3)(x^{2} + 4x \u2212 1) = 2x^{3} + 8x^{2} \u2212 2x \u2212 3x^{2} \u2212 12x + 3 = 2x^{3} + 5x^{2} \u2212 14x + 3</div>\n<p class=\"tip\">Pour \u00e9viter les oublis, multipliez toujours terme par terme dans le m\u00eame ordre et cochez chaque produit.</p>`},\n{h:\"La division de polyn\u00f4mes\", html:`\n<p>Diviser P(x) par D(x), c'est trouver un quotient Q(x) et un reste R(x) tels que :</p>\n<div class=\"formula\">\n<div>P(x) = D(x) \u00b7 Q(x) + R(x) &nbsp;&nbsp; avec degr\u00e9 de R &lt; degr\u00e9 de D</div>\n</div>\n<p>Si le diviseur est x \u2212 a, le <b>th\u00e9or\u00e8me du reste</b> dit que le reste vaut P(a).</p>\n<div class=\"ex\"><b>Exemple</b> (x^{3} + 2x^{2} \u2212 5x + 6) \u00f7 (x \u2212 2) : quotient x^{2} + 4x + 3 et reste 12. On le v\u00e9rifie avec P(2) = 8 + 8 \u2212 10 + 6 = 12.</div>\n<p>Quand le reste est nul, le diviseur est un facteur : x^{2} \u2212 5x + 6 = (x \u2212 2)(x \u2212 3).</p>`},\n{h:\"Les fractions alg\u00e9briques\", html:`\n<p>Une fraction alg\u00e9brique est un quotient de polyn\u00f4mes. Les valeurs qui annulent le d\u00e9nominateur sont <b>interdites</b>.</p>\n<ul>\n<li><b>Simplifier :</b> factoriser le num\u00e9rateur et le d\u00e9nominateur, puis \u00e9liminer les facteurs communs.</li>\n<li><b>Multiplier :</b> multiplier les num\u00e9rateurs entre eux et les d\u00e9nominateurs entre eux (apr\u00e8s simplification).</li>\n<li><b>Diviser :</b> multiplier par l'inverse de la deuxi\u00e8me fraction.</li>\n<li><b>Additionner :</b> mettre au m\u00eame d\u00e9nominateur, puis additionner les num\u00e9rateurs.</li>\n</ul>\n<div class=\"ex\"><b>Exemple</b> [[x^{2} \u2212 4|x^{2} \u2212 2x]] = [[(x \u2212 2)(x + 2)|x(x \u2212 2)]] = [[x + 2|x]] &nbsp; (x \u2260 0 et x \u2260 2)</div>\n<div class=\"ex\"><b>Exemple</b> [[1|x]] + [[2|x + 1]] = [[(x + 1) + 2x|x(x + 1)]] = [[3x + 1|x(x + 1)]]</div>`}\n],\nq:[\n{p:\"D\u00e9velopper (x + 3)(x \u2212 5).\", o:[\"x^{2} \u2212 2x \u2212 15\",\"x^{2} + 2x \u2212 15\",\"x^{2} \u2212 8x \u2212 15\",\"x^{2} \u2212 15\"], a:0, e:\"x \u00b7 x + x \u00b7 (\u22125) + 3 \u00b7 x + 3 \u00b7 (\u22125) = x^{2} \u2212 5x + 3x \u2212 15 = x^{2} \u2212 2x \u2212 15.\"},\n{p:\"D\u00e9velopper (2x \u2212 1)(x^{2} + 3x + 2).\", o:[\"2x^{3} + 5x^{2} + x \u2212 2\",\"2x^{3} + 7x^{2} + x \u2212 2\",\"2x^{3} + 5x^{2} + 7x \u2212 2\",\"2x^{3} + 6x^{2} + 4x \u2212 2\"], a:0, e:\"2x^{3} + 6x^{2} + 4x \u2212 x^{2} \u2212 3x \u2212 2 = 2x^{3} + 5x^{2} + x \u2212 2.\"},\n{p:\"Quel est le degr\u00e9 du produit (x^{3} \u2212 2x)(4x^{2} + 1) ?\", o:[\"5\",\"6\",\"3\",\"2\"], a:0, e:\"Le degr\u00e9 d'un produit est la somme des degr\u00e9s : 3 + 2 = 5.\"},\n{p:\"Quel est le reste de la division de x^{3} + 2x^{2} \u2212 5x + 6 par x \u2212 2 ?\", o:[\"12\",\"0\",\"16\",\"6\"], a:0, e:\"Th\u00e9or\u00e8me du reste : P(2) = 8 + 8 \u2212 10 + 6 = 12.\"},\n{p:\"Quel est le quotient de (x^{2} \u2212 5x + 6) \u00f7 (x \u2212 2) ?\", o:[\"x \u2212 3\",\"x + 3\",\"x \u2212 2\",\"x \u2212 6\"], a:0, e:\"x^{2} \u2212 5x + 6 = (x \u2212 2)(x \u2212 3), donc le quotient est x \u2212 3 et le reste est nul.\"},\n{p:\"Quel est le quotient de (2x^{2} + x \u2212 6) \u00f7 (x + 2) ?\", o:[\"2x \u2212 3\",\"2x + 3\",\"x \u2212 3\",\"2x \u2212 4\"], a:0, e:\"(x + 2)(2x \u2212 3) = 2x^{2} \u2212 3x + 4x \u2212 6 = 2x^{2} + x \u2212 6. Le reste est nul.\"},\n{p:\"Quelles sont les valeurs interdites de [[3|x^{2} \u2212 9]] ?\", o:[\"x = 3 et x = \u22123\",\"x = 3\",\"x = 9\",\"x = 0\"], a:0, e:\"On r\u00e9sout x^{2} \u2212 9 = 0, soit (x \u2212 3)(x + 3) = 0 : x = 3 ou x = \u22123.\"},\n{p:\"Simplifier [[x^{2} \u2212 4|x^{2} \u2212 2x]].\", o:[\"[[x + 2|x]]\",\"[[x \u2212 2|x]]\",\"[[x + 2|x \u2212 2]]\",\"[[\u22124|\u22122x]]\"], a:0, e:\"Num\u00e9rateur : (x \u2212 2)(x + 2). D\u00e9nominateur : x(x \u2212 2). On simplifie le facteur x \u2212 2.\"},\n{p:\"Effectuer [[1|x]] + [[2|x + 1]].\", o:[\"[[3x + 1|x(x + 1)]]\",\"[[3|2x + 1]]\",\"[[3x + 2|x(x + 1)]]\",\"[[x + 3|x(x + 1)]]\"], a:0, e:\"D\u00e9nominateur commun x(x + 1) : [[(x + 1) + 2x|x(x + 1)]] = [[3x + 1|x(x + 1)]]. On n'additionne jamais les d\u00e9nominateurs.\"},\n{p:\"Effectuer [[x^{2} \u2212 1|x]] \u00f7 [[x + 1|x^{2}]].\", o:[\"x(x \u2212 1)\",\"[[x \u2212 1|x]]\",\"x \u2212 1\",\"[[(x + 1)^{2}|x^{3}]]\"], a:0, e:\"On multiplie par l'inverse : [[(x \u2212 1)(x + 1)|x]] \u00b7 [[x^{2}|x + 1]] = x(x \u2212 1).\"}\n]});\n\nCH.push({\nid:2, titre:\"La factorisation\",\nresume:\"Mise en \u00e9vidence double, trin\u00f4mes, diff\u00e9rence de carr\u00e9s, compl\u00e9tion du carr\u00e9, \u00e9quations du 2e degr\u00e9.\",\ncours:[\n{h:\"Mise en \u00e9vidence et factorisation d'un trin\u00f4me\", html:`\n<p>Toujours commencer par la mise en \u00e9vidence d'un facteur commun : 3x^{2} \u2212 12x = 3x(x \u2212 4).</p>\n<p><b>Mise en \u00e9vidence double :</b> grouper les termes deux par deux. Pour factoriser ax^{2} + bx + c, on cherche deux nombres dont le produit est a \u00b7 c et la somme est b, puis on d\u00e9compose le terme du milieu.</p>\n<div class=\"ex\"><b>Exemple</b> 2x^{2} + 7x + 3 : a \u00b7 c = 6, somme 7, donc 1 et 6.<br>\n2x^{2} + 6x + x + 3 = 2x(x + 3) + (x + 3) = (x + 3)(2x + 1)</div>`},\n{h:\"Trin\u00f4me carr\u00e9 parfait et diff\u00e9rence de carr\u00e9s\", html:`\n<div class=\"formula\">\n<div>a^{2} + 2ab + b^{2} = (a + b)^{2} &nbsp;&nbsp; a^{2} \u2212 2ab + b^{2} = (a \u2212 b)^{2}</div>\n<div>a^{2} \u2212 b^{2} = (a \u2212 b)(a + b)</div>\n</div>\n<div class=\"ex\"><b>Exemples</b> 4x^{2} \u2212 12x + 9 = (2x \u2212 3)^{2} &nbsp; et &nbsp; 9x^{2} \u2212 16 = (3x \u2212 4)(3x + 4)</div>\n<p class=\"tip\">Un trin\u00f4me est un carr\u00e9 parfait quand le double produit des racines des deux carr\u00e9s est \u00e9gal au terme du milieu.</p>`},\n{h:\"La compl\u00e9tion du carr\u00e9\", html:`\n<p>Ajouter et retrancher le carr\u00e9 de la moiti\u00e9 du coefficient de x pour obtenir une forme (x + h)^{2} + k.</p>\n<div class=\"ex\"><b>Exemple</b> x^{2} + 8x + 3 = (x^{2} + 8x + 16) \u2212 16 + 3 = (x + 4)^{2} \u2212 13</div>\n<div class=\"ex\"><b>Si a \u2260 1</b> 2x^{2} + 12x + 5 = 2(x^{2} + 6x) + 5 = 2(x + 3)^{2} \u2212 18 + 5 = 2(x + 3)^{2} \u2212 13</div>`},\n{h:\"Factoriser pour manipuler les fractions alg\u00e9briques\", html:`\n<p>La factorisation permet de simplifier et de trouver un d\u00e9nominateur commun.</p>\n<div class=\"ex\"><b>Exemple</b> [[x^{2} \u2212 9|x^{2} + 6x + 9]] = [[(x \u2212 3)(x + 3)|(x + 3)^{2}]] = [[x \u2212 3|x + 3]] &nbsp; (x \u2260 \u22123)</div>`},\n{h:\"La r\u00e9solution d'une \u00e9quation du second degr\u00e9\", html:`\n<p>Trois outils : factorisation, racine carr\u00e9e (si b = 0) et formule quadratique.</p>\n<div class=\"formula\">\n<div>x = [[\u2212b \u00b1 \u221a{b^{2} \u2212 4ac}|2a]] &nbsp;&nbsp; \u0394 = b^{2} \u2212 4ac</div>\n</div>\n<ul>\n<li>\u0394 &gt; 0 : deux solutions. \u0394 = 0 : une solution. \u0394 &lt; 0 : aucune solution r\u00e9elle.</li>\n<li>Somme des solutions : \u2212[[b|a]]. Produit : [[c|a]].</li>\n</ul>\n<div class=\"ex\"><b>Exemple</b> 2x^{2} \u2212 x \u2212 6 = 0 : (2x + 3)(x \u2212 2) = 0, donc x = 2 ou x = \u2212[[3|2]].</div>`}\n],\nq:[\n{p:\"Factoriser x^{2} \u2212 49.\", o:[\"(x \u2212 7)(x + 7)\",\"(x \u2212 7)^{2}\",\"(x + 7)^{2}\",\"(x \u2212 49)(x + 1)\"], a:0, e:\"Diff\u00e9rence de carr\u00e9s : a^{2} \u2212 b^{2} = (a \u2212 b)(a + b) avec a = x et b = 7.\"},\n{p:\"Factoriser x^{2} + 5x + 6.\", o:[\"(x + 2)(x + 3)\",\"(x + 1)(x + 6)\",\"(x \u2212 2)(x \u2212 3)\",\"(x + 5)(x + 1)\"], a:0, e:\"On cherche deux nombres de produit 6 et de somme 5 : 2 et 3.\"},\n{p:\"Factoriser compl\u00e8tement 3x^{2} \u2212 12x.\", o:[\"3x(x \u2212 4)\",\"3x(x \u2212 12)\",\"x(3x \u2212 4)\",\"3(x \u2212 4)\"], a:0, e:\"Le facteur commun est 3x : 3x^{2} \u00f7 3x = x et 12x \u00f7 3x = 4.\"},\n{p:\"Factoriser 2x^{2} + 7x + 3.\", o:[\"(2x + 1)(x + 3)\",\"(2x + 3)(x + 1)\",\"(2x \u2212 1)(x \u2212 3)\",\"(x + 7)(2x + 3)\"], a:0, e:\"a \u00b7 c = 6 et somme 7 : 1 et 6. 2x^{2} + 6x + x + 3 = 2x(x + 3) + (x + 3) = (2x + 1)(x + 3).\"},\n{p:\"Factoriser 4x^{2} \u2212 12x + 9.\", o:[\"(2x \u2212 3)^{2}\",\"(2x + 3)^{2}\",\"(4x \u2212 3)(x \u2212 3)\",\"(2x \u2212 3)(2x + 3)\"], a:0, e:\"4x^{2} = (2x)^{2}, 9 = 3^{2} et le double produit vaut 2 \u00b7 2x \u00b7 3 = 12x. C'est (2x \u2212 3)^{2}.\"},\n{p:\"\u00c9crire x^{2} + 8x + 3 sous la forme (x + h)^{2} + k.\", o:[\"(x + 4)^{2} \u2212 13\",\"(x + 4)^{2} + 3\",\"(x + 8)^{2} \u2212 61\",\"(x \u2212 4)^{2} \u2212 13\"], a:0, e:\"(x + 4)^{2} = x^{2} + 8x + 16. Pour retrouver +3, on retranche 13.\"},\n{p:\"Simplifier [[x^{2} \u2212 9|x^{2} + 6x + 9]].\", o:[\"[[x \u2212 3|x + 3]]\",\"[[x + 3|x \u2212 3]]\",\"[[\u22123|3]]\",\"[[x \u2212 3|6]]\"], a:0, e:\"Num\u00e9rateur : (x \u2212 3)(x + 3). D\u00e9nominateur : (x + 3)^{2}. On simplifie un facteur (x + 3).\"},\n{p:\"R\u00e9soudre 2x^{2} \u2212 x \u2212 6 = 0.\", o:[\"x = 2 ou x = \u2212[[3|2]]\",\"x = \u22122 ou x = [[3|2]]\",\"x = 3 ou x = \u22122\",\"x = 6 ou x = \u22121\"], a:0, e:\"2x^{2} \u2212 x \u2212 6 = (2x + 3)(x \u2212 2) = 0. On v\u00e9rifie : \u0394 = 1 + 48 = 49, x = [[1 \u00b1 7|4]].\"},\n{p:\"Pour quelle valeur de k l'\u00e9quation x^{2} + 4x + k = 0 a-t-elle exactement une solution ?\", o:[\"k = 4\",\"k = 2\",\"k = 8\",\"k = 16\"], a:0, e:\"Il faut \u0394 = 0 : 16 \u2212 4k = 0, donc k = 4.\"},\n{p:\"L'aire d'un rectangle est de 48 cm\u00b2. Sa longueur d\u00e9passe sa largeur de 2 cm. Quelle est sa largeur ?\", o:[\"6 cm\",\"8 cm\",\"4 cm\",\"12 cm\"], a:0, e:\"w(w + 2) = 48 donne w^{2} + 2w \u2212 48 = 0, soit (w + 8)(w \u2212 6) = 0. La largeur est 6 cm (la solution n\u00e9gative est rejet\u00e9e).\"}\n]});\n\nCH.push({\nid:3, titre:\"L'\u00e9tude des fonctions\",\nresume:\"Propri\u00e9t\u00e9s d'une fonction, param\u00e8tres de transformation, fonction partie enti\u00e8re.\",\ncours:[\n{h:\"Les fonctions et leurs propri\u00e9t\u00e9s\", html:`\n<ul>\n<li><b>Domaine :</b> valeurs permises de x. Il exclut les valeurs qui annulent un d\u00e9nominateur ou rendent un radicand n\u00e9gatif.</li>\n<li><b>Image :</b> valeurs prises par y.</li>\n<li><b>Z\u00e9ros :</b> valeurs de x pour lesquelles f(x) = 0. <b>Ordonn\u00e9e \u00e0 l'origine :</b> f(0).</li>\n<li><b>Croissance, d\u00e9croissance, extremums, signe</b> : se lisent sur le graphique.</li>\n</ul>\n<div class=\"ex\"><b>Exemple</b> f(x) = \u221a{x \u2212 4} + 1 : il faut x \u2212 4 \u2265 0, donc dom f = [4, +\u221e[. Pour f(x) = [[5|x + 2]], dom f = \u211d \\\\ {\u22122}.</div>`},\n{h:\"Les param\u00e8tres d'une fonction\", html:`\n<div class=\"formula\">\n<div>g(x) = a \u00b7 f(b(x \u2212 h)) + k</div>\n</div>\n<ul>\n<li><b>a :</b> \u00e9tirement vertical ; r\u00e9flexion par rapport \u00e0 l'axe des x si a &lt; 0</li>\n<li><b>b :</b> \u00e9tirement horizontal de facteur [[1||b|]] ; r\u00e9flexion par rapport \u00e0 l'axe des y si b &lt; 0</li>\n<li><b>h :</b> translation horizontale (vers la droite si h &gt; 0)</li>\n<li><b>k :</b> translation verticale (vers le haut si k &gt; 0)</li>\n</ul>\n<p>Fonctions de base : x^{2}, |x|, \u221ax, [[1|x]]. Pour f(x) = a|x \u2212 h| + k, le sommet est (h, k). Pour f(x) = [[a|x \u2212 h]] + k, les asymptotes sont x = h et y = k.</p>\n<p>Valeur absolue : |x \u2212 a| = b donne x = a + b ou x = a \u2212 b ; |x \u2212 a| &lt; b \u00e9quivaut \u00e0 a \u2212 b &lt; x &lt; a + b.</p>`},\n{h:\"La fonction partie enti\u00e8re : une fonction en escalier\", html:`\n<p>[x] est le plus grand entier inf\u00e9rieur ou \u00e9gal \u00e0 x. Le graphique de f(x) = [x] est un escalier : sur chaque intervalle [n, n + 1[, la fonction est constante et vaut n.</p>\n<div class=\"formula\">\n<div>[3,7] = 3 &nbsp;&nbsp; [5] = 5 &nbsp;&nbsp; [\u22122,3] = \u22123</div>\n</div>\n<p class=\"tip\">Pour un nombre n\u00e9gatif, on recule vers l'entier plus petit : [\u22122,3] vaut \u22123, pas \u22122.</p>\n<p>Avec des param\u00e8tres : f(x) = a[b(x \u2212 h)] + k, utile pour mod\u00e9liser des tarifs par tranche (stationnement, livraison).</p>`}\n],\nq:[\n{p:\"Quel est le domaine de f(x) = \u221a{x \u2212 4} + 1 ?\", o:[\"[4, +\u221e[\",\"]4, +\u221e[\",\"[\u22124, +\u221e[\",\"[1, +\u221e[\"], a:0, e:\"Il faut x \u2212 4 \u2265 0, donc x \u2265 4. La valeur 4 est permise (le radicand vaut 0).\"},\n{p:\"Quel est le domaine de f(x) = [[5|x + 2]] ?\", o:[\"\u211d \\\\ {\u22122}\",\"\u211d \\\\ {2}\",\"\u211d\",\"]\u22122, +\u221e[\"], a:0, e:\"Le d\u00e9nominateur s'annule pour x = \u22122. Cette valeur est interdite.\"},\n{p:\"Quel est le sommet de f(x) = |x + 3| \u2212 2 ?\", o:[\"(\u22123, \u22122)\",\"(3, \u22122)\",\"(\u22123, 2)\",\"(3, 2)\"], a:0, e:\"|x + 3| = |x \u2212 (\u22123)| : h = \u22123. Le sommet est (\u22123, \u22122).\"},\n{p:\"Quelle est l'image de f(x) = \u2212|x| + 4 ?\", o:[\"]\u2212\u221e, 4]\",\"[4, +\u221e[\",\"\u211d\",\"[0, 4]\"], a:0, e:\"|x| \u2265 0, donc \u2212|x| \u2264 0 et f(x) \u2264 4. Le maximum 4 est atteint en x = 0.\"},\n{p:\"Par rapport \u00e0 f(x) = \u221ax, la courbe de g(x) = \u2212\u221a{x + 2} est obtenue par :\", o:[\"une r\u00e9flexion par rapport \u00e0 l'axe des x et une translation de 2 vers la gauche\",\"une r\u00e9flexion par rapport \u00e0 l'axe des y et une translation de 2 vers la droite\",\"une translation de 2 vers le haut seulement\",\"une r\u00e9flexion par rapport \u00e0 l'axe des x et une translation de 2 vers le bas\"], a:0, e:\"Le signe \u2212 devant la racine r\u00e9fl\u00e9chit sur l'axe des x. Le x + 2 = x \u2212 (\u22122) d\u00e9place de 2 unit\u00e9s vers la gauche.\"},\n{p:\"Que vaut [\u22122,3] ?\", o:[\"\u22123\",\"\u22122\",\"2\",\"\u22122,3\"], a:0, e:\"La partie enti\u00e8re est le plus grand entier inf\u00e9rieur ou \u00e9gal au nombre. Pour \u22122,3, c'est \u22123.\"},\n{p:\"Si f(x) = [x] + 2, que vaut f(3,9) ?\", o:[\"5\",\"6\",\"4\",\"3\"], a:0, e:\"[3,9] = 3, donc f(3,9) = 3 + 2 = 5.\"},\n{p:\"Pour quelles valeurs de x a-t-on [x] = 4 ?\", o:[\"4 \u2264 x &lt; 5\",\"3 &lt; x \u2264 4\",\"3,5 \u2264 x &lt; 4,5\",\"x = 4 seulement\"], a:0, e:\"La partie enti\u00e8re vaut 4 sur l'intervalle [4, 5[ (4 inclus, 5 exclu).\"},\n{p:\"Si f(x) = [[6|x]], que vaut f(\u22123) ?\", o:[\"\u22122\",\"2\",\"\u221218\",\"18\"], a:0, e:\"f(\u22123) = [[6|\u22123]] = \u22122.\"},\n{p:\"R\u00e9soudre |2x \u2212 1| &lt; 5.\", o:[\"]\u22122, 3[\",\"]\u22123, 2[\",\"]\u2212\u221e, \u22122[ \u222a ]3, +\u221e[\",\"[\u22122, 3]\"], a:0, e:\"\u22125 &lt; 2x \u2212 1 &lt; 5, donc \u22124 &lt; 2x &lt; 6, soit \u22122 &lt; x &lt; 3. L'in\u00e9galit\u00e9 est stricte : crochets ouverts.\"}\n]});\n\nCH.push({\nid:4, titre:\"La fonction polynomiale du second degr\u00e9\",\nresume:\"R\u00e8gle et propri\u00e9t\u00e9s, diff\u00e9rentes notations, recherche de la r\u00e8gle, in\u00e9quations du 2e degr\u00e9. Explorateur interactif inclus.\",\nexplorer:true,\ncours:[\n{h:\"R\u00e8gle et propri\u00e9t\u00e9s\", html:`\n<div class=\"formula\">\n<div>G\u00e9n\u00e9rale : f(x) = ax^{2} + bx + c</div>\n<div>Canonique : f(x) = a(x \u2212 h)^{2} + k &nbsp; sommet (h, k)</div>\n<div>Factoris\u00e9e : f(x) = a(x \u2212 x_{1})(x \u2212 x_{2}) &nbsp; z\u00e9ros x_{1} et x_{2}</div>\n</div>\n<ul>\n<li><b>Ouverture :</b> vers le haut si a &gt; 0 (minimum k), vers le bas si a &lt; 0 (maximum k).</li>\n<li><b>Axe de sym\u00e9trie :</b> x = h = \u2212[[b|2a]]</li>\n<li><b>Ordonn\u00e9e \u00e0 l'origine :</b> f(0) = c</li>\n<li><b>Image :</b> [k, +\u221e[ si a &gt; 0, ]\u2212\u221e, k] si a &lt; 0</li>\n</ul>\n<div class=\"ex\"><b>Exemple</b> f(x) = x^{2} \u2212 6x + 4 : h = [[6|2]] = 3 et k = f(3) = \u22125. Sommet (3, \u22125), minimum \u22125.</div>`},\n{h:\"Les diff\u00e9rentes notations : passer d'une forme \u00e0 l'autre\", html:`\n<p>Chaque forme r\u00e9pond rapidement \u00e0 une question : la canonique donne le sommet, la factoris\u00e9e donne les z\u00e9ros, la g\u00e9n\u00e9rale donne l'ordonn\u00e9e \u00e0 l'origine.</p>\n<div class=\"ex\"><b>G\u00e9n\u00e9rale \u2192 canonique</b> (compl\u00e9tion du carr\u00e9) x^{2} + 8x + 3 = (x + 4)^{2} \u2212 13</div>\n<div class=\"ex\"><b>Canonique \u2192 g\u00e9n\u00e9rale</b> (d\u00e9velopper) 2(x \u2212 1)^{2} + 3 = 2x^{2} \u2212 4x + 5</div>\n<div class=\"ex\"><b>G\u00e9n\u00e9rale \u2192 factoris\u00e9e</b> x^{2} \u2212 2x \u2212 8 = (x \u2212 4)(x + 2)</div>`},\n{h:\"La recherche de la r\u00e8gle\", html:`\n<p>Choisir la forme selon les donn\u00e9es : sommet et un point (forme canonique), deux z\u00e9ros et un point (forme factoris\u00e9e), trois points (syst\u00e8me d'\u00e9quations sur a, b et c).</p>\n<div class=\"ex\"><b>Exemple</b> Sommet (1, 2), passe par (0, 3) : 3 = a(0 \u2212 1)^{2} + 2, donc a = 1 et f(x) = (x \u2212 1)^{2} + 2.</div>`},\n{h:\"La r\u00e9solution d'une in\u00e9quation du second degr\u00e9 \u00e0 une variable\", html:`\n<ol>\n<li>Ramener l'in\u00e9quation \u00e0 la forme f(x) \u2265 0 (ou \u2264, &gt;, &lt;).</li>\n<li>Trouver les z\u00e9ros de f.</li>\n<li>Imaginer la parabole : si a &gt; 0, elle est positive \u00e0 l'ext\u00e9rieur des z\u00e9ros et n\u00e9gative entre eux.</li>\n</ol>\n<div class=\"ex\"><b>Exemple</b> x^{2} \u2212 x \u2212 12 \u2264 0 : z\u00e9ros \u22123 et 4, parabole ouverte vers le haut. Solution : [\u22123, 4]</div>`}\n],\nq:[\n{p:\"Quel est le sommet de f(x) = (x \u2212 3)^{2} + 5 ?\", o:[\"(3, 5)\",\"(\u22123, 5)\",\"(3, \u22125)\",\"(5, 3)\"], a:0, e:\"Dans a(x \u2212 h)^{2} + k, le sommet est (h, k). Ici h = 3 (attention au signe) et k = 5.\"},\n{p:\"Quelle est l'\u00e9quation de l'axe de sym\u00e9trie de f(x) = \u22122x^{2} + 4x + 1 ?\", o:[\"x = 1\",\"x = \u22121\",\"x = 2\",\"x = [[1|2]]\"], a:0, e:\"h = \u2212[[b|2a]] = \u2212[[4|\u22124]] = 1.\"},\n{p:\"Quelle est la valeur minimale de f(x) = x^{2} \u2212 6x + 4 ?\", o:[\"\u22125\",\"3\",\"4\",\"\u22129\"], a:0, e:\"h = 3 et f(3) = 9 \u2212 18 + 4 = \u22125. Le minimum est la deuxi\u00e8me coordonn\u00e9e du sommet.\"},\n{p:\"Quels sont les z\u00e9ros de f(x) = x^{2} \u2212 2x \u2212 8 ?\", o:[\"\u22122 et 4\",\"2 et \u22124\",\"\u22122 et \u22124\",\"8 et \u22121\"], a:0, e:\"x^{2} \u2212 2x \u2212 8 = (x \u2212 4)(x + 2). Les z\u00e9ros sont 4 et \u22122.\"},\n{p:\"Quelle est l'ordonn\u00e9e \u00e0 l'origine de f(x) = \u2212(x + 1)^{2} + 9 ?\", o:[\"8\",\"9\",\"10\",\"\u22121\"], a:0, e:\"f(0) = \u2212(1)^{2} + 9 = 8.\"},\n{p:\"Une parabole a pour sommet (1, 2) et passe par (0, 3). Quelle est sa r\u00e8gle ?\", o:[\"f(x) = (x \u2212 1)^{2} + 2\",\"f(x) = 3(x \u2212 1)^{2} + 2\",\"f(x) = (x + 1)^{2} + 2\",\"f(x) = \u2212(x \u2212 1)^{2} + 2\"], a:0, e:\"3 = a(0 \u2212 1)^{2} + 2 donne a = 1. Seule la premi\u00e8re option a le sommet (1, 2) et passe par (0, 3).\"},\n{p:\"\u00c9crire f(x) = 2(x \u2212 1)^{2} + 3 sous la forme g\u00e9n\u00e9rale.\", o:[\"2x^{2} \u2212 4x + 5\",\"2x^{2} \u2212 2x + 4\",\"2x^{2} + 4x + 5\",\"2x^{2} \u2212 4x + 3\"], a:0, e:\"2(x^{2} \u2212 2x + 1) + 3 = 2x^{2} \u2212 4x + 2 + 3 = 2x^{2} \u2212 4x + 5.\"},\n{p:\"La hauteur d'un ballon est h(t) = \u22125t^{2} + 20t + 1 (en m\u00e8tres, t en secondes). Quelle est sa hauteur maximale ?\", o:[\"21 m\",\"20 m\",\"41 m\",\"1 m\"], a:0, e:\"t = \u2212[[20|\u221210]] = 2 s, puis h(2) = \u221220 + 40 + 1 = 21 m.\"},\n{p:\"R\u00e9soudre x^{2} \u2212 x \u2212 12 \u2264 0.\", o:[\"[\u22123, 4]\",\"]\u2212\u221e, \u22123] \u222a [4, +\u221e[\",\"[\u22124, 3]\",\"]\u22123, 4[\"], a:0, e:\"Les z\u00e9ros sont \u22123 et 4. La parabole est n\u00e9gative entre les z\u00e9ros, et l'in\u00e9galit\u00e9 large inclut les z\u00e9ros.\"},\n{p:\"R\u00e9soudre x^{2} &gt; 9.\", o:[\"x &lt; \u22123 ou x &gt; 3\",\"\u22123 &lt; x &lt; 3\",\"x &gt; 3\",\"x &lt; \u22129 ou x &gt; 9\"], a:0, e:\"x^{2} \u2212 9 &gt; 0 : la parabole est positive \u00e0 l'ext\u00e9rieur des z\u00e9ros \u22123 et 3.\"}\n]});\n\nCH.push({\nid:5, titre:\"Les triangles et les figures \u00e9quivalentes\",\nresume:\"Triangles isom\u00e9triques, triangles semblables, relations m\u00e9triques dans le triangle rectangle, figures \u00e9quivalentes.\",\ncours:[\n{h:\"Les triangles isom\u00e9triques\", html:`\n<p>Deux triangles sont <b>isom\u00e9triques</b> (\u2245) quand leurs c\u00f4t\u00e9s et leurs angles homologues sont \u00e9gaux. Pour le prouver, il suffit de v\u00e9rifier l'un de ces cas :</p>\n<ul>\n<li><b>CCC :</b> trois c\u00f4t\u00e9s homologues \u00e9gaux</li>\n<li><b>CAC :</b> deux c\u00f4t\u00e9s \u00e9gaux et l'angle compris entre eux \u00e9gal</li>\n<li><b>ACA :</b> deux angles \u00e9gaux et le c\u00f4t\u00e9 compris entre eux \u00e9gal</li>\n</ul>\n<p class=\"tip\">Deux triangles dont trois angles sont \u00e9gaux ne sont pas forc\u00e9ment isom\u00e9triques : ils sont seulement semblables.</p>`},\n{h:\"Les triangles semblables\", html:`\n<p>Deux triangles sont <b>semblables</b> (\u223c) quand leurs angles homologues sont \u00e9gaux et leurs c\u00f4t\u00e9s homologues sont proportionnels. Cas suffisants : <b>AA</b> (deux angles \u00e9gaux), <b>CAC</b> proportionnel, <b>CCC</b> proportionnel.</p>\n<div class=\"formula\">\n<div>Rapport de similitude k = [[longueur dans la figure image|longueur homologue dans la figure initiale]]</div>\n<div>longueurs \u00d7 k &nbsp;&nbsp; aires \u00d7 k^{2} &nbsp;&nbsp; volumes \u00d7 k^{3}</div>\n</div>\n<div class=\"ex\"><b>Exemple</b> ABC \u223c DEF avec AB = 6, DE = 9 et BC = 8 : k = [[9|6]] = 1,5, donc EF = 8 \u00d7 1,5 = 12.</div>`},\n{h:\"Les relations m\u00e9triques dans un triangle rectangle\", html:`\n<p>Soit un triangle rectangle d'hypot\u00e9nuse a, de cath\u00e8tes b et c, et de hauteur h issue de l'angle droit. Cette hauteur partage l'hypot\u00e9nuse en deux segments m (adjacent \u00e0 c) et n (adjacent \u00e0 b).</p>\n<div class=\"formula\">\n<div>c^{2} = a \u00b7 m &nbsp;&nbsp; b^{2} = a \u00b7 n</div>\n<div>h^{2} = m \u00b7 n</div>\n<div>b \u00b7 c = a \u00b7 h</div>\n<div>a^{2} = b^{2} + c^{2} (Pythagore)</div>\n</div>\n<div class=\"ex\"><b>Exemple</b> Cath\u00e8tes 6 et 8 : a = 10 et h = [[6 \u00d7 8|10]] = 4,8.</div>\n<p class=\"tip\">Triplets pythagoriciens courants : (3, 4, 5), (5, 12, 13), (8, 15, 17), (7, 24, 25).</p>`},\n{h:\"Les figures \u00e9quivalentes\", html:`\n<p>Deux figures sont <b>\u00e9quivalentes</b> si elles ont la m\u00eame aire (ou le m\u00eame volume), m\u00eame si leur forme est diff\u00e9rente.</p>\n<div class=\"formula\">\n<div>Triangle : [[b \u00d7 h|2]] &nbsp;&nbsp; Trap\u00e8ze : [[(B + b) \u00d7 h|2]] &nbsp;&nbsp; Cercle : \u03c0r^{2}</div>\n</div>\n<div class=\"ex\"><b>Exemple</b> Un carr\u00e9 de c\u00f4t\u00e9 6 (aire 36) est \u00e9quivalent \u00e0 un rectangle de largeur 4 et de longueur 9.</div>`}\n],\nq:[\n{p:\"Deux triangles ont deux c\u00f4t\u00e9s \u00e9gaux, ainsi que l'angle compris entre ces c\u00f4t\u00e9s. Quel cas d'isom\u00e9trie s'applique ?\", o:[\"CAC\",\"ACA\",\"CCC\",\"AA\"], a:0, e:\"Deux c\u00f4t\u00e9s et l'angle compris : c\u00f4t\u00e9-angle-c\u00f4t\u00e9 (CAC). AA n'est pas un cas d'isom\u00e9trie, seulement de similitude.\"},\n{p:\"ABC \u223c DEF avec AB = 6, DE = 9 et BC = 8. Quelle est la longueur EF ?\", o:[\"12\",\"10\",\"5,3\",\"14\"], a:0, e:\"Le rapport de similitude est [[9|6]] = 1,5. EF = 8 \u00d7 1,5 = 12.\"},\n{p:\"Deux triangles semblables ont un rapport de similitude de 3. Le plus petit a une aire de 20 cm\u00b2. Quelle est l'aire du plus grand ?\", o:[\"180 cm\u00b2\",\"60 cm\u00b2\",\"540 cm\u00b2\",\"120 cm\u00b2\"], a:0, e:\"Les aires sont multipli\u00e9es par k^{2} = 9 : 20 \u00d7 9 = 180 cm\u00b2.\"},\n{p:\"Dans un triangle rectangle, la hauteur issue de l'angle droit divise l'hypot\u00e9nuse en segments de 4 et de 9. Quelle est la mesure de cette hauteur ?\", o:[\"6\",\"36\",\"6,5\",\"13\"], a:0, e:\"h^{2} = m \u00b7 n = 4 \u00d7 9 = 36, donc h = 6.\"},\n{p:\"Un triangle rectangle a une hypot\u00e9nuse de 25. La projection d'une cath\u00e8te sur l'hypot\u00e9nuse mesure 9. Quelle est la longueur de cette cath\u00e8te ?\", o:[\"15\",\"20\",\"16\",\"9\"], a:0, e:\"c^{2} = a \u00b7 m = 25 \u00d7 9 = 225, donc c = 15.\"},\n{p:\"Les cath\u00e8tes d'un triangle rectangle mesurent 6 et 8. Quelle est la hauteur issue de l'angle droit ?\", o:[\"4,8\",\"5\",\"3,6\",\"7\"], a:0, e:\"L'hypot\u00e9nuse est 10. Avec b \u00b7 c = a \u00b7 h : 48 = 10h, donc h = 4,8.\"},\n{p:\"Lequel de ces triplets est pythagoricien ?\", o:[\"(5, 12, 13)\",\"(6, 8, 11)\",\"(4, 5, 6)\",\"(7, 9, 12)\"], a:0, e:\"5^{2} + 12^{2} = 25 + 144 = 169 = 13^{2}. Les autres ne v\u00e9rifient pas a^{2} + b^{2} = c^{2}.\"},\n{p:\"Un carr\u00e9 de c\u00f4t\u00e9 6 est \u00e9quivalent \u00e0 un rectangle de largeur 4. Quelle est la longueur du rectangle ?\", o:[\"9\",\"6\",\"8\",\"12\"], a:0, e:\"Aire du carr\u00e9 : 36. Longueur du rectangle : 36 \u00f7 4 = 9.\"},\n{p:\"Quelle est l'aire d'un trap\u00e8ze dont les bases mesurent 10 et 6 et dont la hauteur est 5 ?\", o:[\"40\",\"80\",\"30\",\"50\"], a:0, e:\"Aire = [[(10 + 6) \u00d7 5|2]] = [[80|2]] = 40.\"},\n{p:\"Un cercle de rayon 5 est \u00e9quivalent \u00e0 un carr\u00e9. Quelle est environ la longueur du c\u00f4t\u00e9 du carr\u00e9 ?\", o:[\"8,86\",\"7,85\",\"5\",\"9,87\"], a:0, e:\"Aire du cercle : 25\u03c0 \u2248 78,54. C\u00f4t\u00e9 du carr\u00e9 : \u221a78,54 \u2248 8,86.\"}\n]});\n\nCH.push({\nid:6, titre:\"Les relations trigonom\u00e9triques\",\nresume:\"Rapports trigonom\u00e9triques, r\u00e9solution de probl\u00e8mes, loi des sinus, loi des cosinus et aire d'un triangle.\",\ncours:[\n{h:\"Les relations trigonom\u00e9triques dans un triangle rectangle\", html:`\n<div class=\"formula\">\n<div>sin \u03b8 = [[c\u00f4t\u00e9 oppos\u00e9|hypot\u00e9nuse]]</div>\n<div>cos \u03b8 = [[c\u00f4t\u00e9 adjacent|hypot\u00e9nuse]]</div>\n<div>tan \u03b8 = [[c\u00f4t\u00e9 oppos\u00e9|c\u00f4t\u00e9 adjacent]]</div>\n</div>\n<p>Pour trouver un angle, on utilise la fonction r\u00e9ciproque : \u03b8 = tan^{\u22121}([[3|4]]) \u2248 36,9\u00b0. Pour deux angles aigus compl\u00e9mentaires : sin \u03b8 = cos(90\u00b0 \u2212 \u03b8).</p>\n<p class=\"tip\">Calculatrice en mode degr\u00e9s ! C'est l'erreur la plus fr\u00e9quente aux examens.</p>`},\n{h:\"La r\u00e9solution de probl\u00e8mes \u00e0 l'aide des relations trigonom\u00e9triques\", html:`\n<p>Faire un sch\u00e9ma, rep\u00e9rer le triangle rectangle, choisir le rapport qui relie ce qu'on conna\u00eet \u00e0 ce qu'on cherche.</p>\n<div class=\"ex\"><b>Exemple</b> \u00c0 20 m de la base d'un arbre, l'angle d'\u00e9l\u00e9vation du sommet est de 35\u00b0 : tan 35\u00b0 = [[h|20]], donc h = 20 tan 35\u00b0 \u2248 14,0 m.</div>`},\n{h:\"La loi des sinus et la loi des cosinus dans un triangle quelconque\", html:`\n<p>Dans un triangle ABC (c\u00f4t\u00e9 a oppos\u00e9 \u00e0 l'angle A, etc.) :</p>\n<div class=\"formula\">\n<div>Loi des sinus : [[a|sin A]] = [[b|sin B]] = [[c|sin C]]</div>\n<div>Loi des cosinus : a^{2} = b^{2} + c^{2} \u2212 2bc \u00b7 cos A</div>\n</div>\n<ul>\n<li><b>Sinus :</b> on conna\u00eet un angle et son c\u00f4t\u00e9 oppos\u00e9, plus une autre donn\u00e9e.</li>\n<li><b>Cosinus :</b> on conna\u00eet deux c\u00f4t\u00e9s et l'angle compris, ou les trois c\u00f4t\u00e9s.</li>\n</ul>\n<div class=\"ex\"><b>Exemple</b> A = 40\u00b0, B = 60\u00b0, a = 10 : b = [[10 \u00b7 sin 60\u00b0|sin 40\u00b0]] \u2248 13,5</div>\n<div class=\"ex\"><b>Exemple</b> b = 7, c = 8, A = 60\u00b0 : a^{2} = 49 + 64 \u2212 2(7)(8)(0,5) = 57, donc a \u2248 7,55.</div>`},\n{h:\"L'aire d'un triangle\", html:`\n<div class=\"formula\">\n<div>Aire = [[1|2]] \u00b7 a \u00b7 b \u00b7 sin C</div>\n</div>\n<div class=\"ex\"><b>Exemple</b> a = 8, b = 10, C = 30\u00b0 : aire = [[1|2]] \u00b7 8 \u00b7 10 \u00b7 0,5 = 20.</div>`}\n],\nq:[\n{p:\"Dans un triangle rectangle, l'hypot\u00e9nuse mesure 10 et un angle aigu vaut 30\u00b0. Quelle est la longueur du c\u00f4t\u00e9 oppos\u00e9 \u00e0 cet angle ?\", o:[\"5\",\"5\u221a3\",\"10\u221a3\",\"[[10|\u221a3]]\"], a:0, e:\"sin 30\u00b0 = [[oppos\u00e9|10]] = 0,5, donc le c\u00f4t\u00e9 oppos\u00e9 mesure 5.\"},\n{p:\"Si tan \u03b8 = [[3|4]], quelle est la mesure de \u03b8 ?\", o:[\"36,9\u00b0\",\"53,1\u00b0\",\"41,4\u00b0\",\"48,6\u00b0\"], a:0, e:\"\u03b8 = tan^{\u22121}(0,75) \u2248 36,9\u00b0. L'angle de 53,1\u00b0 est son compl\u00e9ment.\"},\n{p:\"Un triangle a des c\u00f4t\u00e9s de 3, 4 et 5. Que vaut le cosinus du plus petit angle ?\", o:[\"[[4|5]]\",\"[[3|5]]\",\"[[3|4]]\",\"[[5|4]]\"], a:0, e:\"Le plus petit angle est oppos\u00e9 au c\u00f4t\u00e9 3. Son c\u00f4t\u00e9 adjacent est 4 : cos \u03b8 = [[4|5]].\"},\n{p:\"\u00c0 20 m de la base d'un arbre, l'angle d'\u00e9l\u00e9vation du sommet est de 35\u00b0. Quelle est la hauteur de l'arbre ?\", o:[\"14,0 m\",\"28,6 m\",\"11,5 m\",\"16,4 m\"], a:0, e:\"tan 35\u00b0 = [[h|20]], donc h = 20 tan 35\u00b0 \u2248 14,0 m.\"},\n{p:\"Laquelle de ces valeurs est \u00e9gale \u00e0 sin 35\u00b0 ?\", o:[\"cos 55\u00b0\",\"cos 35\u00b0\",\"tan 55\u00b0\",\"sin 55\u00b0\"], a:0, e:\"Pour des angles compl\u00e9mentaires (35\u00b0 + 55\u00b0 = 90\u00b0), sin 35\u00b0 = cos 55\u00b0.\"},\n{p:\"Dans un triangle ABC, A = 40\u00b0, B = 60\u00b0 et a = 10. Quelle est la longueur b ?\", o:[\"13,5\",\"7,4\",\"11,5\",\"15,6\"], a:0, e:\"Loi des sinus : b = [[10 \u00b7 sin 60\u00b0|sin 40\u00b0]] \u2248 [[8,66|0,643]] \u2248 13,5.\"},\n{p:\"Dans un triangle, b = 7, c = 8 et A = 60\u00b0. Quelle est la longueur a ?\", o:[\"7,55\",\"10,63\",\"8,12\",\"5,29\"], a:0, e:\"a^{2} = 49 + 64 \u2212 2(7)(8)cos 60\u00b0 = 113 \u2212 56 = 57, donc a \u2248 7,55. Oublier le terme en cosinus donnerait 10,63.\"},\n{p:\"Un triangle a des c\u00f4t\u00e9s de 5, 6 et 7. Quel est l'angle oppos\u00e9 au c\u00f4t\u00e9 de 7 ?\", o:[\"78,5\u00b0\",\"101,5\u00b0\",\"57,1\u00b0\",\"44,4\u00b0\"], a:0, e:\"Loi des cosinus : cos C = [[25 + 36 \u2212 49|2(5)(6)]] = 0,2, donc C \u2248 78,5\u00b0.\"},\n{p:\"Quelle est l'aire d'un triangle dont deux c\u00f4t\u00e9s mesurent 8 et 10 avec un angle compris de 30\u00b0 ?\", o:[\"20\",\"40\",\"34,6\",\"80\"], a:0, e:\"Aire = [[1|2]] \u00b7 8 \u00b7 10 \u00b7 sin 30\u00b0 = 40 \u00d7 0,5 = 20.\"},\n{p:\"Quelle loi faut-il utiliser pour trouver le troisi\u00e8me c\u00f4t\u00e9 d'un triangle quelconque quand on conna\u00eet deux c\u00f4t\u00e9s et l'angle compris ?\", o:[\"La loi des cosinus\",\"La loi des sinus\",\"Le th\u00e9or\u00e8me de Pythagore\",\"Le rapport tangente\"], a:0, e:\"La loi des sinus exige un angle et son c\u00f4t\u00e9 oppos\u00e9 connus. Ici, l'angle est entre les deux c\u00f4t\u00e9s : loi des cosinus.\"}\n]});\n\nCH.push({\nid:7, titre:\"Les droites et les in\u00e9quations \u00e0 deux variables\",\nresume:\"Pente, droites parall\u00e8les et perpendiculaires, distance, formes d'\u00e9quation d'une droite, in\u00e9quations \u00e0 deux variables.\",\ncours:[\n{h:\"G\u00e9om\u00e9trie analytique : pente, droites parall\u00e8les et perpendiculaires, distance\", html:`\n<div class=\"formula\">\n<div>d(A, B) = \u221a{(x_{2} \u2212 x_{1})^{2} + (y_{2} \u2212 y_{1})^{2}}</div>\n<div>m = [[y_{2} \u2212 y_{1}|x_{2} \u2212 x_{1}]]</div>\n</div>\n<ul>\n<li>Droites <b>parall\u00e8les</b> : m\u00eame pente.</li>\n<li>Droites <b>perpendiculaires</b> : m_{1} \u00b7 m_{2} = \u22121 (pentes oppos\u00e9es et inverses).</li>\n</ul>\n<div class=\"ex\"><b>Exemple</b> A(1, 2) et B(7, 10) : d = \u221a{36 + 64} = 10. Pente de la droite par (1, 3) et (5, 11) : [[8|4]] = 2.</div>`},\n{h:\"Les diff\u00e9rentes formes d'\u00e9quation d'une droite\", html:`\n<div class=\"formula\">\n<div>Fonctionnelle : y = mx + b</div>\n<div>G\u00e9n\u00e9rale : Ax + By + C = 0 &nbsp; (pente \u2212[[A|B]])</div>\n<div>Sym\u00e9trique : [[x|a]] + [[y|b]] = 1 &nbsp; (coupe les axes en a et en b)</div>\n</div>\n<div class=\"ex\"><b>Exemple</b> Parall\u00e8le \u00e0 y = 2x + 5 passant par (1, 4) : y \u2212 4 = 2(x \u2212 1), donc y = 2x + 2.</div>\n<div class=\"ex\"><b>Exemple</b> Droite par (2, 1) et (6, 9) : m = 2 et 1 = 2(2) + b, donc y = 2x \u2212 3.</div>`},\n{h:\"Les in\u00e9quations du premier degr\u00e9 \u00e0 deux variables\", html:`\n<p>Tracer la droite fronti\u00e8re (trait plein si \u2264 ou \u2265, pointill\u00e9 si &lt; ou &gt;), puis tester un point (souvent l'origine) pour savoir quel c\u00f4t\u00e9 colorier.</p>\n<div class=\"ex\"><b>Exemple</b> y &gt; 2x \u2212 1 : r\u00e9gion au-dessus de la droite, fronti\u00e8re exclue. Le point (0, 0) convient car 0 &gt; \u22121.</div>`},\n{h:\"Les in\u00e9quations du second degr\u00e9 \u00e0 deux variables\", html:`\n<p>M\u00eame m\u00e9thode, avec une parabole comme fronti\u00e8re : y \u2265 ax^{2} + bx + c colorie l'int\u00e9rieur de la parabole (au-dessus), y \u2264 \u2026 colorie l'ext\u00e9rieur (au-dessous), si a &gt; 0.</p>\n<div class=\"ex\"><b>Exemple</b> y \u2264 x^{2} \u2212 4 : le point (0, \u22125) convient car \u22125 \u2264 \u22124, mais (0, 0) ne convient pas car 0 &gt; \u22124.</div>`}\n],\nq:[\n{p:\"Quelle est la distance entre A(1, 2) et B(7, 10) ?\", o:[\"10\",\"14\",\"8\",\"100\"], a:0, e:\"d = \u221a{6^{2} + 8^{2}} = \u221a{36 + 64} = \u221a100 = 10.\"},\n{p:\"Quelle est la pente de la droite passant par (1, 3) et (5, 11) ?\", o:[\"2\",\"[[1|2]]\",\"\u22122\",\"4\"], a:0, e:\"m = [[11 \u2212 3|5 \u2212 1]] = [[8|4]] = 2.\"},\n{p:\"Quelle est la pente d'une droite perpendiculaire \u00e0 y = \u2212[[2|3]]x + 1 ?\", o:[\"[[3|2]]\",\"\u2212[[3|2]]\",\"[[2|3]]\",\"\u2212[[2|3]]\"], a:0, e:\"Le produit des pentes doit valoir \u22121 : \u2212[[2|3]] \u00d7 [[3|2]] = \u22121.\"},\n{p:\"Quelle est l'\u00e9quation de la droite parall\u00e8le \u00e0 y = 2x + 5 qui passe par (1, 4) ?\", o:[\"y = 2x + 2\",\"y = 2x + 4\",\"y = \u2212[[1|2]]x + 4,5\",\"y = [[1|2]]x + 3,5\"], a:0, e:\"La pente reste 2. De 4 = 2(1) + b, on tire b = 2.\"},\n{p:\"Quelle est l'\u00e9quation de la droite passant par (2, 1) et (6, 9) ?\", o:[\"y = 2x \u2212 3\",\"y = 2x + 3\",\"y = [[1|2]]x\",\"y = 4x \u2212 7\"], a:0, e:\"m = [[9 \u2212 1|6 \u2212 2]] = 2. De 1 = 2(2) + b, on tire b = \u22123.\"},\n{p:\"Quelle est la pente de la droite d'\u00e9quation 2x \u2212 3y + 6 = 0 ?\", o:[\"[[2|3]]\",\"\u2212[[2|3]]\",\"[[3|2]]\",\"2\"], a:0, e:\"On isole y : 3y = 2x + 6, donc y = [[2|3]]x + 2. La pente est [[2|3]].\"},\n{p:\"En quel point la droite d'\u00e9quation [[x|4]] + [[y|3]] = 1 coupe-t-elle l'axe des y ?\", o:[\"(0, 3)\",\"(0, 4)\",\"(0, [[3|4]])\",\"(0, 12)\"], a:0, e:\"Dans la forme sym\u00e9trique [[x|a]] + [[y|b]] = 1, b est l'ordonn\u00e9e \u00e0 l'origine. Ici b = 3.\"},\n{p:\"Lequel de ces points est dans la r\u00e9gion y &gt; 2x \u2212 1 (fronti\u00e8re exclue) ?\", o:[\"(0, 0)\",\"(1, 1)\",\"(2, 3)\",\"(0, \u22121)\"], a:0, e:\"Pour (0, 0) : 0 &gt; \u22121, vrai. Les autres points sont sur la droite : 1 = 1, 3 = 3 et \u22121 = \u22121, donc ils sont exclus.\"},\n{p:\"Lequel de ces points v\u00e9rifie y \u2264 x^{2} \u2212 4 ?\", o:[\"(0, \u22125)\",\"(0, 0)\",\"(3, 6)\",\"(1, \u22122)\"], a:0, e:\"Pour (0, \u22125) : \u22125 \u2264 \u22124, vrai. Pour (0, 0) : 0 \u2264 \u22124 faux. Pour (3, 6) : 6 \u2264 5 faux. Pour (1, \u22122) : \u22122 \u2264 \u22123 faux.\"},\n{p:\"Quelle r\u00e9gion repr\u00e9sente l'in\u00e9quation y \u2265 2x \u2212 1 ?\", o:[\"Au-dessus de la droite, fronti\u00e8re incluse\",\"Au-dessous de la droite, fronti\u00e8re incluse\",\"Au-dessus de la droite, fronti\u00e8re exclue\",\"Au-dessous de la droite, fronti\u00e8re exclue\"], a:0, e:\"y \u2265 signifie \u00ab au-dessus \u00bb. Le symbole \u2265 inclut la fronti\u00e8re (trait plein).\"}\n]});\n\nCH.push({\nid:8, titre:\"Les syst\u00e8mes d'\u00e9quations\",\nresume:\"Comparaison, substitution, r\u00e9duction, nombre de solutions, syst\u00e8mes form\u00e9s d'une droite et d'une parabole.\",\ncours:[\n{h:\"Comparaison et nombre de solutions d'un syst\u00e8me du premier degr\u00e9\", html:`\n<p><b>Comparaison :</b> isoler la m\u00eame variable dans les deux \u00e9quations, puis \u00e9galer les expressions.</p>\n<div class=\"ex\"><b>Exemple</b> y = 2x + 1 et y = \u2212x + 7 : 2x + 1 = \u2212x + 7, donc x = 2 et y = 5.</div>\n<ul>\n<li>Pentes diff\u00e9rentes : une solution (droites s\u00e9cantes).</li>\n<li>M\u00eame pente, ordonn\u00e9es diff\u00e9rentes : aucune solution (droites parall\u00e8les).</li>\n<li>Droites confondues : une infinit\u00e9 de solutions.</li>\n</ul>`},\n{h:\"La r\u00e9solution par substitution\", html:`\n<p>Isoler une variable dans une \u00e9quation et la remplacer dans l'autre.</p>\n<div class=\"ex\"><b>Exemple</b> y = 2x \u2212 1 et 3x + y = 9 : 3x + 2x \u2212 1 = 9, donc x = 2 et y = 3. Solution (2, 3).</div>`},\n{h:\"La r\u00e9solution par r\u00e9duction\", html:`\n<p>Additionner ou soustraire les \u00e9quations (apr\u00e8s avoir multipli\u00e9 au besoin) pour \u00e9liminer une variable.</p>\n<div class=\"ex\"><b>Exemple</b> 2x + 3y = 12 et 4x \u2212 3y = 6 : on additionne, 6x = 18, donc x = 3, puis y = 2.</div>`},\n{h:\"Les syst\u00e8mes form\u00e9s d'une \u00e9quation du premier degr\u00e9 et d'une \u00e9quation du second degr\u00e9\", html:`\n<p>On \u00e9gale les deux r\u00e8gles pour obtenir une \u00e9quation du second degr\u00e9 en x, puis on calcule les y correspondants. Il y a 0, 1 ou 2 solutions.</p>\n<div class=\"ex\"><b>Exemple</b> y = x + 1 et y = x^{2} \u2212 1 : x^{2} \u2212 x \u2212 2 = 0, donc x = 2 ou x = \u22121. Points d'intersection : (2, 3) et (\u22121, 0).</div>`}\n],\nq:[\n{p:\"R\u00e9soudre le syst\u00e8me x + y = 7 et x \u2212 y = 1.\", o:[\"(4, 3)\",\"(3, 4)\",\"(5, 2)\",\"(6, 1)\"], a:0, e:\"On additionne : 2x = 8, donc x = 4, puis y = 3.\"},\n{p:\"R\u00e9soudre y = 2x \u2212 1 et 3x + y = 9.\", o:[\"(2, 3)\",\"(3, 2)\",\"(1, 1)\",\"(2, \u22123)\"], a:0, e:\"Par substitution : 3x + 2x \u2212 1 = 9, donc x = 2 et y = 3.\"},\n{p:\"R\u00e9soudre 2x + 3y = 12 et 4x \u2212 3y = 6.\", o:[\"(3, 2)\",\"(2, 3)\",\"(4, 1)\",\"(1, 4)\"], a:0, e:\"On additionne : 6x = 18, donc x = 3. Puis 2(3) + 3y = 12 donne y = 2.\"},\n{p:\"Combien de solutions poss\u00e8de le syst\u00e8me 2x + 4y = 6 et x + 2y = 3 ?\", o:[\"Une infinit\u00e9\",\"Aucune\",\"Une seule\",\"Deux\"], a:0, e:\"La premi\u00e8re \u00e9quation est le double de la seconde : les droites sont confondues.\"},\n{p:\"Combien de solutions poss\u00e8de 2x + y = 5 et 4x + 2y = 7 ?\", o:[\"Aucune\",\"Une\",\"Deux\",\"Une infinit\u00e9\"], a:0, e:\"En divisant la seconde par 2 : 2x + y = 3,5. M\u00eame pente que la premi\u00e8re, ordonn\u00e9es diff\u00e9rentes : droites parall\u00e8les.\"},\n{p:\"Quels sont les points d'intersection de y = x + 1 et y = x^{2} \u2212 1 ?\", o:[\"(2, 3) et (\u22121, 0)\",\"(2, 3) seulement\",\"(\u22122, \u22121) et (1, 2)\",\"(\u22121, 0) et (1, 2)\"], a:0, e:\"x^{2} \u2212 1 = x + 1 donne x^{2} \u2212 x \u2212 2 = 0, soit x = 2 ou x = \u22121. Les ordonn\u00e9es : y = 3 et y = 0.\"},\n{p:\"Deux cahiers et trois crayons co\u00fbtent 11 $. Un cahier et deux crayons co\u00fbtent 6 $. Quel est le prix d'un cahier ?\", o:[\"4 $\",\"3 $\",\"2 $\",\"5 $\"], a:0, e:\"c = 6 \u2212 2k dans la seconde, puis 2(6 \u2212 2k) + 3k = 11 donne k = 1 $ et c = 4 $.\"},\n{p:\"Deux nombres ont pour somme 10 et pour produit 21. Quels sont-ils ?\", o:[\"3 et 7\",\"2 et 8\",\"5 et 5\",\"1 et 9\"], a:0, e:\"Ce sont les solutions de t^{2} \u2212 10t + 21 = 0, soit (t \u2212 3)(t \u2212 7) = 0.\"},\n{p:\"Un syst\u00e8me form\u00e9 d'une droite et d'une parabole a au plus combien de solutions ?\", o:[\"2\",\"1\",\"3\",\"4\"], a:0, e:\"L'\u00e9quation obtenue est de degr\u00e9 2 : elle a au plus 2 solutions.\"},\n{p:\"Deux nombres ont pour somme 15 et pour diff\u00e9rence 3. Quel est le plus grand ?\", o:[\"9\",\"6\",\"12\",\"10\"], a:0, e:\"x + y = 15 et x \u2212 y = 3 donnent 2x = 18, donc x = 9.\"}\n]});\n\nCH.push({\nid:9, titre:\"La statistique\",\nresume:\"Distribution \u00e0 deux caract\u00e8res, corr\u00e9lation lin\u00e9aire, coefficient de corr\u00e9lation, droite de r\u00e9gression.\",\ncours:[\n{h:\"La distribution \u00e0 deux caract\u00e8res et la corr\u00e9lation lin\u00e9aire\", html:`\n<p>On \u00e9tudie deux variables mesur\u00e9es sur les m\u00eames individus. Le <b>nuage de points</b> montre le lien entre elles.</p>\n<ul>\n<li><b>Corr\u00e9lation positive :</b> le nuage monte de gauche \u00e0 droite (y augmente avec x).</li>\n<li><b>Corr\u00e9lation n\u00e9gative :</b> le nuage descend (y diminue quand x augmente).</li>\n<li><b>Corr\u00e9lation nulle :</b> aucun alignement visible.</li>\n<li>Plus les points sont proches d'une droite, plus la corr\u00e9lation est <b>forte</b>.</li>\n</ul>`},\n{h:\"Le coefficient de corr\u00e9lation lin\u00e9aire\", html:`\n<div class=\"formula\">\n<div>\u22121 \u2264 r \u2264 1</div>\n</div>\n<ul>\n<li>Le signe de r donne le sens ; |r| donne la force.</li>\n<li>|r| proche de 1 : corr\u00e9lation forte. |r| proche de 0 : corr\u00e9lation faible ou nulle.</li>\n<li>r = 1 ou r = \u22121 : tous les points sont exactement align\u00e9s.</li>\n</ul>\n<p class=\"tip\">Corr\u00e9lation n'est pas causalit\u00e9 : deux variables peuvent \u00e9voluer ensemble \u00e0 cause d'un troisi\u00e8me facteur (variable cach\u00e9e).</p>`},\n{h:\"La droite de r\u00e9gression\", html:`\n<p>La droite de r\u00e9gression y = ax + b r\u00e9sume la tendance du nuage. Sa pente a indique la variation moyenne de y quand x augmente de 1.</p>\n<ul>\n<li><b>Interpolation :</b> pr\u00e9dire \u00e0 l'int\u00e9rieur de l'\u00e9tendue des donn\u00e9es (assez fiable).</li>\n<li><b>Extrapolation :</b> pr\u00e9dire en dehors de cette \u00e9tendue (risqu\u00e9e).</li>\n</ul>\n<div class=\"ex\"><b>Exemple</b> y = 2x + 3 : pour x = 5, y pr\u00e9vu = 2(5) + 3 = 13.</div>`}\n],\nq:[\n{p:\"Un nuage de points monte nettement de la gauche vers la droite. Quel type de corr\u00e9lation observe-t-on ?\", o:[\"Positive\",\"N\u00e9gative\",\"Nulle\",\"Impossible \u00e0 dire\"], a:0, e:\"Quand y augmente avec x, la corr\u00e9lation est positive.\"},\n{p:\"Un coefficient de corr\u00e9lation vaut r = \u22120,92. Que peut-on conclure ?\", o:[\"La corr\u00e9lation est forte et n\u00e9gative\",\"La corr\u00e9lation est faible et n\u00e9gative\",\"La corr\u00e9lation est forte et positive\",\"Il n'y a pas de corr\u00e9lation\"], a:0, e:\"|r| est proche de 1 (corr\u00e9lation forte) et le signe \u2212 indique que y diminue quand x augmente.\"},\n{p:\"Un coefficient de corr\u00e9lation vaut r = 0,15. Que peut-on conclure ?\", o:[\"La corr\u00e9lation lin\u00e9aire est tr\u00e8s faible\",\"La corr\u00e9lation est forte et positive\",\"La corr\u00e9lation est forte et n\u00e9gative\",\"Les points sont parfaitement align\u00e9s\"], a:0, e:\"|r| est proche de 0 : il n'y a presque pas de lien lin\u00e9aire.\"},\n{p:\"Laquelle de ces valeurs ne peut pas \u00eatre un coefficient de corr\u00e9lation ?\", o:[\"1,2\",\"\u22120,8\",\"0\",\"\u22121\"], a:0, e:\"Un coefficient de corr\u00e9lation est toujours compris entre \u22121 et 1.\"},\n{p:\"Les points (1, 2), (2, 4), (3, 6) et (4, 8) sont align\u00e9s sur y = 2x. Que vaut r ?\", o:[\"1\",\"2\",\"0\",\"\u22121\"], a:0, e:\"Points parfaitement align\u00e9s sur une droite croissante : r = 1.\"},\n{p:\"La droite de r\u00e9gression est y = 2x + 3. Quelle valeur de y pr\u00e9voit-on pour x = 5 ?\", o:[\"13\",\"10\",\"15\",\"8\"], a:0, e:\"y = 2(5) + 3 = 13.\"},\n{p:\"La droite de r\u00e9gression passe par (0, 10) et (5, 35). Quelle est son \u00e9quation ?\", o:[\"y = 5x + 10\",\"y = 7x + 10\",\"y = 5x + 35\",\"y = 10x + 5\"], a:0, e:\"Pente : [[35 \u2212 10|5 \u2212 0]] = 5. Ordonn\u00e9e \u00e0 l'origine : 10.\"},\n{p:\"Une droite de r\u00e9gression est y = \u22121,5x + 40. Que signifie la pente ?\", o:[\"Quand x augmente de 1, y diminue en moyenne de 1,5\",\"Quand x augmente de 1, y augmente en moyenne de 1,5\",\"Quand x vaut 0, y vaut \u22121,5\",\"Quand y augmente de 1, x diminue de 1,5\"], a:0, e:\"La pente est la variation moyenne de y pour une augmentation de 1 de x. Elle est n\u00e9gative : y diminue.\"},\n{p:\"Les donn\u00e9es de x vont de 10 \u00e0 50. Pr\u00e9dire y pour x = 80 avec la droite de r\u00e9gression est :\", o:[\"Une extrapolation, moins fiable\",\"Une interpolation, tr\u00e8s fiable\",\"Une interpolation, moins fiable\",\"Une extrapolation, tr\u00e8s fiable\"], a:0, e:\"x = 80 est en dehors de l'\u00e9tendue des donn\u00e9es : c'est une extrapolation, donc risqu\u00e9e.\"},\n{p:\"Les ventes de cr\u00e8me glac\u00e9e et les coups de soleil sont fortement corr\u00e9l\u00e9s. Quelle conclusion est la plus appropri\u00e9e ?\", o:[\"Une variable cach\u00e9e, la chaleur, peut expliquer les deux\",\"La cr\u00e8me glac\u00e9e cause les coups de soleil\",\"Les coups de soleil causent les ventes de cr\u00e8me glac\u00e9e\",\"Les donn\u00e9es sont forc\u00e9ment fausses\"], a:0, e:\"Une corr\u00e9lation n'implique pas une causalit\u00e9. Il fait chaud : on ach\u00e8te plus de cr\u00e8me glac\u00e9e et on attrape plus de coups de soleil.\"}\n]});\n\n(function(){\nvar CH = window.CH;\nCH.forEach(function(c){ c.q.forEach(function(q){ q.ch = c.id; }); });\nvar app = document.getElementById('app');\n\n/* ---------- utilitaires ---------- */\nfunction fmt(s){\n  return String(s)\n    .replace(/\\^\\{([^{}]*)\\}/g,'<sup>$1</sup>')\n    .replace(/_\\{([^{}]*)\\}/g,'<sub>$1</sub>')\n    .replace(/\u221a\\{([^{}]*)\\}/g,'<span class=\"rad\">\u221a<span class=\"rc\">$1</span></span>')\n    .replace(/\\[\\[(.+?)\\|(.+?)\\]\\]/g,'<span class=\"fr\"><span>$1</span><span>$2</span></span>');\n}\nfunction shuffle(a){ a=a.slice(); for(var i=a.length-1;i>0;i--){var j=Math.floor(Math.random()*(i+1));var t=a[i];a[i]=a[j];a[j]=t;} return a; }\nfunction nf(n){ return String(+n.toFixed(2)).replace('.',','); }\nfunction chap(id){ return CH.filter(function(c){return c.id===id;})[0]; }\nfunction mention(p){ return p>=90?'Excellent':p>=80?'Tr\u00e8s bien':p>=70?'Bien':p>=60?'Passable':'\u00c0 retravailler'; }\nfunction mmss(s){ s=Math.max(0,Math.round(s)); return Math.floor(s/60)+':'+('0'+(s%60)).slice(-2); }\nvar LET=['A','B','C','D','E'];\n\nvar KEY='sn4-v1', S={quiz:{},hist:[]};\ntry{ var raw=localStorage.getItem(KEY); if(raw){ var o=JSON.parse(raw); S.quiz=o.quiz||{}; S.hist=o.hist||[]; } }catch(e){}\nfunction save(){ try{ localStorage.setItem(KEY,JSON.stringify(S)); }catch(e){} }\n\n/* ---------- routeur ---------- */\nvar cur=null, tick=null;\nfunction stopTimer(){ if(tick){ clearInterval(tick); tick=null; } }\nfunction setNav(k){\n  var links=document.querySelectorAll('#nav a');\n  for(var i=0;i<links.length;i++){ if(links[i].getAttribute('data-k')===k) links[i].setAttribute('aria-current','page'); else links[i].removeAttribute('aria-current'); }\n}\nfunction route(){\n  var h=(location.hash||'#accueil').slice(1);\n  var m=h.match(/^(cours|quiz)-(\\d+)$/);\n  stopTimer(); cur=null;\n  window.scrollTo(0,0);\n  if(m && chap(+m[2])){ setNav('accueil'); return chapter(+m[2],m[1]); }\n  if(h==='tests'){ setNav('tests'); return builder('test'); }\n  if(h==='examens'){ setNav('examens'); return builder('exam'); }\n  setNav('accueil'); home();\n}\nwindow.addEventListener('hashchange',route);\n\n/* ---------- accueil ---------- */\nfunction home(){\n  var done=0, sum=0;\n  CH.forEach(function(c){ var b=S.quiz[c.id]; if(b!=null){ done++; sum+=b; } });\n  var nq=CH.reduce(function(n,c){return n+c.q.length;},0);\n  var html='<section class=\"intro\"><p class=\"eyebrow\">Math\u00e9matique \u00b7 Sciences naturelles \u00b7 4e secondaire</p>'+\n   '<h1>Atelier <mark>Maths</mark> SN4</h1>'+\n   '<p class=\"lead\">Un cours r\u00e9sum\u00e9 par chapitre, des quiz corrig\u00e9s pas \u00e0 pas, puis des tests et des examens chronom\u00e9tr\u00e9s pour mesurer ce qui est acquis.</p>'+\n   '<div class=\"summary\"><span><b>'+CH.length+'</b>chapitres</span><span><b>'+nq+'</b>questions</span><span><b>'+done+'/'+CH.length+'</b>quiz faits</span>'+\n   (done?'<span><b>'+Math.round(sum/done)+' %</b>moyenne des meilleurs quiz</span>':'')+'</div></section>';\n  html+='<h2 style=\"margin-bottom:.8rem\">Les chapitres</h2><ul class=\"list\">';\n  CH.forEach(function(c){\n    var b=S.quiz[c.id];\n    html+='<li class=\"row\"><span class=\"num\">'+c.id+'</span><div><h3>'+fmt(c.titre)+'</h3><p>'+fmt(c.resume)+'</p>'+\n      '<div class=\"bar\" aria-hidden=\"true\"><i style=\"width:'+(b||0)+'%\"></i></div>'+\n      '<div class=\"best\">'+(b!=null?'Meilleur quiz : '+b+' %':'Quiz pas encore tent\u00e9')+'</div></div>'+\n      '<div class=\"acts\"><a class=\"btn-s\" href=\"#cours-'+c.id+'\">Cours</a><a class=\"btn\" href=\"#quiz-'+c.id+'\">Quiz</a></div></li>';\n  });\n  html+='</ul><div class=\"two\"><div class=\"panel\"><h2>Tests</h2><p class=\"muted\">Choisissez les chapitres \u00e0 r\u00e9viser et le nombre de questions. Corrig\u00e9 d\u00e9taill\u00e9 \u00e0 la fin.</p><a class=\"btn\" href=\"#tests\">Composer un test</a></div>'+\n   '<div class=\"panel\"><h2>Examens</h2><p class=\"muted\">Conditions r\u00e9elles : chronom\u00e8tre, pas de correction avant la fin, bilan par chapitre.</p><a class=\"btn\" href=\"#examens\">Passer un examen</a></div></div>';\n  html+='<div class=\"panel\"><h2>Derniers r\u00e9sultats</h2>';\n  if(S.hist.length){\n    html+='<ul class=\"hist\">'+S.hist.slice(0,8).map(function(r){\n      return '<li><span>'+r.titre+'</span><span><b>'+r.pct+' %</b> \u00b7 '+r.date+'</span></li>';}).join('')+'</ul>';\n  } else html+='<p class=\"muted\" style=\"margin:0\">Aucun r\u00e9sultat pour l\\'instant. Les scores sont gard\u00e9s dans ce navigateur.</p>';\n  html+='</div>';\n  app.innerHTML=html;\n}\n\n/* ---------- chapitre ---------- */\nfunction chapter(id,tab){\n  var c=chap(id);\n  var prev=chap(id-1), next=chap(id+1);\n  var html='<div class=\"crumb\"><a href=\"#accueil\">\u2190 Tous les chapitres</a><span>'+\n    (prev?'<a href=\"#'+tab+'-'+prev.id+'\">Chapitre '+prev.id+'</a>':'')+(prev&&next?' \u00b7 ':'')+(next?'<a href=\"#'+tab+'-'+next.id+'\">Chapitre '+next.id+' \u2192</a>':'')+'</span></div>'+\n    '<p class=\"eyebrow\">Chapitre '+id+'</p><h1 style=\"font-size:clamp(1.7rem,5vw,2.5rem)\">'+fmt(c.titre)+'</h1>'+\n    '<div class=\"tabs\"><a href=\"#cours-'+id+'\"'+(tab==='cours'?' aria-current=\"page\"':'')+'>Cours</a><a href=\"#quiz-'+id+'\"'+(tab==='quiz'?' aria-current=\"page\"':'')+'>Quiz (10 questions)</a></div><div id=\"pane\"></div>';\n  app.innerHTML=html;\n  var pane=document.getElementById('pane');\n  if(tab==='cours'){\n    var h='';\n    c.cours.forEach(function(s){ h+='<article class=\"sec\"><h2>'+fmt(s.h)+'</h2>'+fmt(s.html)+'</article>'; });\n    if(c.explorer) h+='<article class=\"sec\"><h2>Explorateur de parabole</h2><div id=\"xp\"></div></article>';\n    h+='<div class=\"cta\"><a class=\"btn\" href=\"#quiz-'+id+'\">Passer au quiz</a><a class=\"btn-s\" href=\"#accueil\">Retour</a></div>';\n    pane.innerHTML=h;\n    if(c.explorer) explorer(document.getElementById('xp'));\n  } else {\n    var b=S.quiz[id];\n    pane.innerHTML='<div class=\"panel\"><h2>Quiz du chapitre</h2><p class=\"muted\">10 questions, correction imm\u00e9diate apr\u00e8s chaque r\u00e9ponse. L\\'ordre des choix change \u00e0 chaque essai.'+(b!=null?' Votre meilleur r\u00e9sultat : <b>'+b+' %</b>.':'')+'</p><button class=\"btn\" id=\"go\">Commencer</button></div>';\n    document.getElementById('go').onclick=function(){\n      start({kind:'quiz',titre:'Quiz \u2014 chapitre '+id,mode:'now',qs:shuffle(c.q),chap:id,seconds:0});\n    };\n  }\n}\n\n/* ---------- explorateur de parabole ---------- */\nfunction explorer(el){\n  el.innerHTML='<div class=\"xp\"><div>'+\n   '<p class=\"tip\" style=\"margin-top:0\">D\u00e9placez les curseurs pour voir comment a, h et k changent la parabole f(x) = a(x \u2212 h)<sup>2</sup> + k.</p>'+\n   '<label>a<input id=\"pa\" type=\"range\" min=\"-3\" max=\"3\" step=\"0.5\" value=\"1\"><output id=\"oa\">1</output></label>'+\n   '<label>h<input id=\"ph\" type=\"range\" min=\"-6\" max=\"6\" step=\"1\" value=\"2\"><output id=\"oh\">2</output></label>'+\n   '<label>k<input id=\"pk\" type=\"range\" min=\"-6\" max=\"6\" step=\"1\" value=\"-3\"><output id=\"ok\">\u22123</output></label>'+\n   '<div class=\"readout\" id=\"ro\"></div></div><svg id=\"sv\" viewBox=\"0 0 384 384\" role=\"img\" aria-label=\"Graphique de la parabole\"></svg></div>';\n  var U=24, C=192;\n  function px(x){return C+x*U;} function py(y){return C-y*U;}\n  function draw(){\n    var a=+document.getElementById('pa').value, h=+document.getElementById('ph').value, k=+document.getElementById('pk').value;\n    if(a===0){ a=0.5; document.getElementById('pa').value=0.5; }\n    document.getElementById('oa').textContent=nf(a); document.getElementById('oh').textContent=String(h).replace('-','\u2212'); document.getElementById('ok').textContent=String(k).replace('-','\u2212');\n    var s='<defs><clipPath id=\"cp\"><rect x=\"0\" y=\"0\" width=\"384\" height=\"384\"/></clipPath></defs>';\n    for(var i=-8;i<=8;i++){ s+='<line class=\"gridl\" x1=\"'+px(i)+'\" y1=\"0\" x2=\"'+px(i)+'\" y2=\"384\"/><line class=\"gridl\" x1=\"0\" y1=\"'+py(i)+'\" x2=\"384\" y2=\"'+py(i)+'\"/>'; }\n    s+='<line class=\"axis\" x1=\"0\" y1=\"'+C+'\" x2=\"384\" y2=\"'+C+'\"/><line class=\"axis\" x1=\"'+C+'\" y1=\"0\" x2=\"'+C+'\" y2=\"384\"/>';\n    s+='<text class=\"svgt\" x=\"372\" y=\"'+(C-5)+'\">x</text><text class=\"svgt\" x=\"'+(C+5)+'\" y=\"12\">y</text>';\n    var d='';\n    for(var xx=-8;xx<=8.001;xx+=0.1){ var yy=a*(xx-h)*(xx-h)+k; d+=(d?'L':'M')+px(xx).toFixed(1)+' '+py(yy).toFixed(1); }\n    s+='<g clip-path=\"url(#cp)\"><path class=\"curve\" d=\"'+d+'\"/></g>';\n    s+='<line x1=\"'+px(h)+'\" y1=\"0\" x2=\"'+px(h)+'\" y2=\"384\" stroke=\"var(--accent)\" stroke-dasharray=\"4 4\" stroke-width=\"1\" opacity=\".6\"/>';\n    var disc=-k/a, zs=[];\n    if(disc>0){ zs=[h-Math.sqrt(disc),h+Math.sqrt(disc)]; } else if(Math.abs(disc)<1e-9){ zs=[h]; }\n    zs.forEach(function(z){ s+='<circle class=\"pz\" cx=\"'+px(z)+'\" cy=\"'+C+'\" r=\"4.5\"/>'; });\n    s+='<circle class=\"pt\" cx=\"'+px(h)+'\" cy=\"'+py(k)+'\" r=\"5\"/>';\n    document.getElementById('sv').innerHTML=s;\n    var A=a, B=-2*a*h, Cc=a*h*h+k;\n    function t(n){ return nf(n).replace('-','\u2212'); }\n    document.getElementById('ro').innerHTML=\n      '<div>Sommet : (<b>'+t(h)+'</b>, <b>'+t(k)+'</b>) &nbsp;\u00b7&nbsp; axe : x = '+t(h)+'</div>'+\n      '<div>Forme g\u00e9n\u00e9rale : '+(A===1?'':A===-1?'\u2212':t(A))+'x<sup>2</sup> '+(B<0?'\u2212':'+')+' '+nf(Math.abs(B))+'x '+(Cc<0?'\u2212':'+')+' '+nf(Math.abs(Cc))+'</div>'+\n      '<div>Ordonn\u00e9e \u00e0 l\\'origine : '+t(Cc)+'</div>'+\n      '<div>Z\u00e9ros : '+(zs.length===0?'aucun':zs.map(t).join(' et '))+'</div>'+\n      '<div>'+(a>0?'Minimum':'Maximum')+' : '+t(k)+'</div>';\n  }\n  ['pa','ph','pk'].forEach(function(id){ document.getElementById(id).addEventListener('input',draw); });\n  draw();\n}\n\n/* ---------- composition des tests et examens ---------- */\nfunction draw(chapters,n){\n  var per={}, base=Math.floor(n/chapters.length), extra=n-base*chapters.length, order=shuffle(chapters);\n  order.forEach(function(id,i){ per[id]=base+(i<extra?1:0); });\n  var out=[];\n  chapters.forEach(function(id){ out=out.concat(shuffle(chap(id).q).slice(0,Math.min(per[id],10))); });\n  return shuffle(out);\n}\nfunction builder(kind){\n  if(kind==='test'){\n    var h='<p class=\"eyebrow\">Tests</p><h1 style=\"font-size:clamp(1.7rem,5vw,2.5rem)\">Composer un test</h1><p class=\"muted\">Les questions sont tir\u00e9es au hasard dans les chapitres choisis.</p>'+\n     '<div class=\"panel form\"><div><b>Chapitres</b><div class=\"chk\" style=\"margin-top:.5rem\">'+\n     CH.map(function(c){ return '<label><input type=\"checkbox\" class=\"cc\" value=\"'+c.id+'\" checked> '+c.id+'. '+fmt(c.titre)+'</label>'; }).join('')+'</div></div>'+\n     '<div class=\"inl\"><label for=\"nq\">Questions&nbsp;<select id=\"nq\"><option>10</option><option selected>15</option><option>20</option><option>30</option></select></label>'+\n     '<label><input type=\"checkbox\" id=\"tm\"> Chronom\u00e8tre&nbsp;<input type=\"number\" id=\"mn\" value=\"30\" min=\"5\" max=\"180\" style=\"width:5.5em\">&nbsp;min</label></div>'+\n     '<div id=\"err\" class=\"warn\" hidden>Choisissez au moins un chapitre.</div>'+\n     '<div><button class=\"btn\" id=\"go\">Lancer le test</button></div></div>';\n    app.innerHTML=h;\n    document.getElementById('go').onclick=function(){\n      var ids=[].slice.call(document.querySelectorAll('.cc')).filter(function(x){return x.checked;}).map(function(x){return +x.value;});\n      if(!ids.length){ document.getElementById('err').hidden=false; return; }\n      var n=Math.min(+document.getElementById('nq').value, ids.length*10);\n      var secs=document.getElementById('tm').checked?Math.max(5,+document.getElementById('mn').value||30)*60:0;\n      start({kind:'test',titre:'Test \u2014 '+(ids.length===CH.length?'tous les chapitres':'chap. '+ids.join(', ')),mode:'end',qs:draw(ids,n),seconds:secs});\n    };\n    return;\n  }\n  var P=[\n   {t:'Examen 1 \u2014 chapitres 1 \u00e0 3',d:'Manipulation d\\'expressions alg\u00e9briques, factorisation, \u00e9tude des fonctions.',ids:[1,2,3],n:18,m:60},\n   {t:'Examen 2 \u2014 chapitres 4 \u00e0 6',d:'Fonction du second degr\u00e9, triangles et figures \u00e9quivalentes, relations trigonom\u00e9triques.',ids:[4,5,6],n:18,m:60},\n   {t:'Examen 3 \u2014 chapitres 7 \u00e0 9',d:'Droites et in\u00e9quations \u00e0 deux variables, syst\u00e8mes d\\'\u00e9quations, statistique.',ids:[7,8,9],n:18,m:60},\n   {t:'Examen final \u2014 tous les chapitres',d:'Toute la mati\u00e8re de l\\'ann\u00e9e, 36 questions r\u00e9parties \u00e9galement.',ids:[1,2,3,4,5,6,7,8,9],n:36,m:120}];\n  var h2='<p class=\"eyebrow\">Examens</p><h1 style=\"font-size:clamp(1.7rem,5vw,2.5rem)\">Passer un examen</h1><p class=\"muted\">Le chronom\u00e8tre d\u00e9marre d\u00e8s le d\u00e9but. La correction n\\'appara\u00eet qu\\'\u00e0 la fin, ou quand le temps est \u00e9coul\u00e9.</p><div class=\"presets\" style=\"margin-top:1.2rem\">'+\n   P.map(function(p,i){ return '<div class=\"panel preset\"><div><h2>'+p.t+'</h2><p class=\"muted\" style=\"margin:0\">'+p.d+'</p><p style=\"margin:.4rem 0 0\"><b>'+p.n+' questions \u00b7 '+p.m+' minutes</b></p></div><button class=\"btn\" data-i=\"'+i+'\">Commencer</button></div>'; }).join('')+'</div>';\n  app.innerHTML=h2;\n  [].forEach.call(document.querySelectorAll('.preset button'),function(b){\n    b.onclick=function(){ var p=P[+b.getAttribute('data-i')]; start({kind:'exam',titre:p.t,mode:'end',qs:draw(p.ids,p.n),seconds:p.m*60}); };\n  });\n}\n\n/* ---------- moteur de session ---------- */\nfunction start(cfg){\n  stopTimer();\n  cur={cfg:cfg,i:0,t0:Date.now(),over:false,confirm:false,\n    items:cfg.qs.map(function(q){\n      return {q:q,sel:null,opts:shuffle(q.o.map(function(t,i){return {t:t,ok:i===q.a};}))};\n    })};\n  if(cfg.seconds){\n    cur.end=Date.now()+cfg.seconds*1000;\n    tick=setInterval(function(){\n      var left=(cur.end-Date.now())/1000, el=document.getElementById('tm');\n      if(el){ el.textContent=mmss(left); el.className='timer'+(left<300?' low':''); }\n      if(left<=0){ finish(true); }\n    },500);\n  }\n  window.scrollTo(0,0);\n  render();\n}\nfunction answered(){ return cur.items.filter(function(x){return x.sel!=null;}).length; }\nfunction render(){\n  var s=cur, cfg=s.cfg, it=s.items[s.i], n=s.items.length, now=cfg.mode==='now';\n  var h='<div class=\"qhead\"><div><p class=\"eyebrow\" style=\"margin:0\">'+cfg.titre+'</p><b>Question '+(s.i+1)+' / '+n+'</b></div>'+\n    (cfg.seconds?'<div class=\"timer\" id=\"tm\">'+mmss((s.end-Date.now())/1000)+'</div>':'')+'</div>'+\n    '<div class=\"qbar\"><i style=\"width:'+Math.round((now?answered():s.i+1)/n*100)+'%\"></i></div><div class=\"qlayout'+(now?' solo':'')+'\"><div>'+\n    '<div class=\"qcard\"><div class=\"qtag\">'+chap(it.q.ch).id+'. '+fmt(chap(it.q.ch).titre)+'</div><div class=\"qtext\">'+fmt(it.q.p)+'</div><div class=\"opts\">';\n  it.opts.forEach(function(o,i){\n    var c='opt';\n    if(now && it.sel!=null){ if(o.ok) c+=' good'; else if(it.sel===i) c+=' bad'; }\n    else if(it.sel===i) c+=' sel';\n    h+='<button class=\"'+c+'\" data-i=\"'+i+'\"'+(now&&it.sel!=null?' disabled':'')+'><span class=\"l\">'+LET[i]+'</span><span>'+fmt(o.t)+'</span></button>';\n  });\n  h+='</div>';\n  if(now && it.sel!=null){\n    var good=it.opts[it.sel].ok;\n    h+='<div class=\"expl\"><b class=\"'+(good?'g':'r')+'\">'+(good?'Bonne r\u00e9ponse.':'Pas tout \u00e0 fait.')+'</b> '+fmt(it.q.e)+'</div>';\n  }\n  h+='</div><div class=\"qnav\"><button class=\"btn-s\" id=\"pv\"'+(s.i===0?' disabled':'')+'>\u2190 Pr\u00e9c\u00e9dente</button>';\n  var last=s.i===n-1;\n  if(now) h+='<button class=\"btn\" id=\"nx\"'+(it.sel==null?' disabled':'')+'>'+(last?'Voir le r\u00e9sultat':'Suivante \u2192')+'</button>';\n  else h+=last?'<button class=\"btn\" id=\"fin\">Terminer</button>':'<button class=\"btn\" id=\"nx\">Suivante \u2192</button>';\n  h+='</div>';\n  if(!now && s.confirm){\n    var miss=n-answered();\n    h+='<div class=\"warn\">'+(miss?'Il reste '+miss+' question'+(miss>1?'s':'')+' sans r\u00e9ponse. ':'Toutes les questions ont une r\u00e9ponse. ')+'Terminer maintenant ?<div class=\"qnav\" style=\"margin-top:.6rem\"><button class=\"btn\" id=\"yes\">Oui, voir la correction</button><button class=\"btn-s\" id=\"no\">Continuer</button></div></div>';\n  }\n  h+='</div>';\n  if(!now){\n    h+='<aside><b style=\"font-size:.9rem\">Navigation</b><div class=\"navg\" style=\"margin-top:.5rem\">'+\n      s.items.map(function(x,i){ return '<button data-n=\"'+i+'\" class=\"'+(x.sel!=null?'done':'')+(i===s.i?' cur':'')+'\" aria-label=\"Question '+(i+1)+'\">'+(i+1)+'</button>'; }).join('')+'</div>'+\n      '<p class=\"tip\" style=\"margin-top:.8rem\">Vous pouvez revenir \u00e0 n\\'importe quelle question avant de terminer.</p><button class=\"btn-s\" id=\"fin2\" style=\"margin-top:.4rem\">Terminer</button></aside>';\n  }\n  h+='</div>';\n  app.innerHTML=h;\n  [].forEach.call(app.querySelectorAll('.opt'),function(b){\n    b.onclick=function(){ it.sel=+b.getAttribute('data-i'); s.confirm=false; render(); };\n  });\n  var $=function(id){return document.getElementById(id);};\n  if($('pv')) $('pv').onclick=function(){ s.i--; s.confirm=false; render(); window.scrollTo(0,0); };\n  if($('nx')) $('nx').onclick=function(){ if(last&&now){ finish(false); } else { s.i++; s.confirm=false; render(); window.scrollTo(0,0); } };\n  var ask=function(){ s.confirm=true; render(); };\n  if($('fin')) $('fin').onclick=ask; if($('fin2')) $('fin2').onclick=ask;\n  if($('yes')) $('yes').onclick=function(){ finish(false); };\n  if($('no')) $('no').onclick=function(){ s.confirm=false; render(); };\n  [].forEach.call(app.querySelectorAll('.navg button'),function(b){ b.onclick=function(){ s.i=+b.getAttribute('data-n'); s.confirm=false; render(); }; });\n}\n\n/* ---------- r\u00e9sultats ---------- */\nfunction finish(timeUp){\n  if(!cur||cur.over) return;\n  var s=cur; s.over=true; stopTimer();\n  var cfg=s.cfg, n=s.items.length;\n  var good=s.items.filter(function(x){return x.sel!=null&&x.opts[x.sel].ok;}).length;\n  var pct=Math.round(good/n*100), used=(Date.now()-s.t0)/1000;\n  if(cfg.kind==='quiz'){ if(S.quiz[cfg.chap]==null||pct>S.quiz[cfg.chap]) S.quiz[cfg.chap]=pct; }\n  var d=new Date(), pad=function(x){return ('0'+x).slice(-2);};\n  S.hist.unshift({titre:cfg.titre,pct:pct,date:pad(d.getDate())+'/'+pad(d.getMonth()+1)}); S.hist=S.hist.slice(0,20);\n  save();\n  var by={};\n  s.items.forEach(function(x){ var c=x.q.ch; by[c]=by[c]||{g:0,n:0}; by[c].n++; if(x.sel!=null&&x.opts[x.sel].ok) by[c].g++; });\n  var h='<p class=\"eyebrow\">'+cfg.titre+'</p>'+(timeUp?'<div class=\"warn\" style=\"margin:0 0 1rem\">Le temps est \u00e9coul\u00e9. Les questions sans r\u00e9ponse comptent comme fausses.</div>':'')+\n   '<div class=\"score\"><span class=\"big\">'+good+' / '+n+'</span><span class=\"big\" style=\"font-size:2rem;color:var(--muted)\">'+pct+' %</span><span class=\"mention\">'+mention(pct)+'</span></div>'+\n   '<p class=\"muted\">Dur\u00e9e : '+mmss(used)+(cfg.seconds?' sur '+mmss(cfg.seconds):'')+'</p>';\n  var ids=Object.keys(by).map(Number).sort(function(a,b){return a-b;});\n  if(ids.length>1){\n    h+='<div class=\"panel\"><h2>Bilan par chapitre</h2><div class=\"bars\">'+ids.map(function(id){\n      var p=Math.round(by[id].g/by[id].n*100);\n      return '<div><span>'+id+'. '+fmt(chap(id).titre)+'</span><span class=\"bar\"><i class=\"'+(p<60?'lo':'')+'\" style=\"width:'+p+'%\"></i></span><span>'+by[id].g+'/'+by[id].n+'</span></div>';}).join('')+'</div>'+\n      (function(){ var weak=ids.filter(function(id){return by[id].g/by[id].n<0.7;}); return weak.length?'<p class=\"tip\" style=\"margin:0\">\u00c0 retravailler : '+weak.map(function(id){return '<a href=\"#cours-'+id+'\">chapitre '+id+'</a>';}).join(', ')+'.</p>':'<p class=\"tip\" style=\"margin:0\">Tous les chapitres sont au-dessus de 70 %. Excellent travail.</p>'; })()+'</div>';\n  }\n  var wrong=s.items.filter(function(x){return !(x.sel!=null&&x.opts[x.sel].ok);});\n  h+='<div class=\"filters\"><button class=\"btn\" id=\"all\">Voir toute la correction</button>'+(wrong.length?'<button class=\"btn-s\" id=\"wr\">Erreurs seulement ('+wrong.length+')</button><button class=\"btn-s\" id=\"redo\">Refaire les erreurs</button>':'')+'<a class=\"btn-s\" href=\"#accueil\">Accueil</a></div><div id=\"rev\"></div>';\n  app.innerHTML=h; window.scrollTo(0,0);\n  function review(list){\n    document.getElementById('rev').innerHTML='<div class=\"rev\">'+list.map(function(x){\n      var ok=x.sel!=null&&x.opts[x.sel].ok, rightIdx=x.opts.findIndex(function(o){return o.ok;});\n      return '<div class=\"qcard\"><div class=\"qtag\">'+x.q.ch+'. '+fmt(chap(x.q.ch).titre)+' \u00b7 <span class=\"'+(ok?'res-ok':'res-no')+'\">'+(ok?'R\u00e9ussie':(x.sel==null?'Sans r\u00e9ponse':'Incorrecte'))+'</span></div>'+\n        '<div class=\"qtext\" style=\"font-size:1.05rem\">'+fmt(x.q.p)+'</div>'+\n        (ok?'':'<p style=\"margin:0 0 .3rem\"><b>Votre r\u00e9ponse :</b> '+(x.sel==null?'\u2014':fmt(x.opts[x.sel].t))+'</p>')+\n        '<p style=\"margin:0 0 .5rem\"><b>Bonne r\u00e9ponse :</b> <span class=\"m\">'+LET[rightIdx]+'. '+fmt(x.opts[rightIdx].t)+'</span></p>'+\n        '<div class=\"expl\" style=\"margin-top:.4rem\">'+fmt(x.q.e)+'</div></div>';}).join('')+'</div>';\n    document.getElementById('rev').scrollIntoView({behavior:'smooth'});\n  }\n  document.getElementById('all').onclick=function(){ review(s.items); };\n  if(document.getElementById('wr')) document.getElementById('wr').onclick=function(){ review(wrong); };\n  if(document.getElementById('redo')) document.getElementById('redo').onclick=function(){\n    start({kind:'redo',titre:'Reprise des erreurs',mode:'now',qs:shuffle(wrong.map(function(x){return x.q;})),seconds:0});\n  };\n}\n\nroute();\n})();\n\n</script>\n</body>\n</html>\n";
